(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c58"]=[{"id":"00006697","register_sub_id":"101","register_pk":"107680","name":"旧羽室家住宅土蔵","kana":"きゅうはむろけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市曽根西町4-59","lat":34.77335145,"lng":135.46294242,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0439","desc":"主屋玄関部の北方に位置する内蔵。桁行２間半梁間２間、東西棟、切妻造桟瓦葺の２階建で、南面西端近くに戸口を設け、妻面の小窓には片開鉄扉を装置し、小庇を付ける。外壁はモルタル塗で、内部は白漆喰塗の真壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006697"},{"id":"00006698","register_sub_id":"101","register_pk":"107681","name":"旧羽室家住宅納屋","kana":"きゅうはむろけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市曽根西町4-59","lat":34.77341017,"lng":135.46312066,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.0㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0440","desc":"主屋東端の台所部の東北方に位置し、南北棟で建つ。桁行２間梁間１間規模、切妻造桟瓦葺の木造平屋建で、北方桁行１間分が増築され、東面は屋根を葺き降ろして土庇状とする。土蔵と同様に、内部は白漆喰塗の真壁とし、外部は大壁造モルタル塗仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006698"},{"id":"00000546","register_sub_id":"101","register_pk":"101536","name":"葛原家住宅（南葛原別邸）主屋","kana":"くずはらけじゅうたく（みなみくずはらべってい）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府富田林市常盤町1-12","lat":34.50022499,"lng":135.59731089,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造２階建，瓦葺，建築面積103㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"27 － 0035","desc":"当時流行したコテージ風の文化住宅の好例である。平面は中廊下式で，玄関・階段・応接間等に分離派の意匠が見られる。２階に個性的な床棚を備えた座敷がある。セメント瓦葺の切妻屋根がＴ字に交差する外観は特異で，地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000546"},{"id":"00000547","register_sub_id":"101","register_pk":"101537","name":"葛原家住宅（南葛原別邸）倉庫","kana":"くずはらけじゅうたく（みなみくずはらべってい）そうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府富田林市常盤町1-12","lat":34.50025819,"lng":135.59720514,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積14㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"27 － 0036","desc":"広大な敷地の一画に建つ小規模な平屋建の付属屋。外壁はモルタル塗で，腰下板貼とし妻側に大きな窓を開き，屋根はセメント瓦を葺く。主屋の背後にあって，簡素な外観ながら一体的につくられており，別邸の屋敷構えを構成する要素の一つとして知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000547"},{"id":"00009650","register_sub_id":"101","register_pk":"194646","name":"小谷家住宅主屋","kana":"こたにけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市南区豊田1612","lat":34.49353226,"lng":135.49794952,"geo_status":"db","era":"江戸中期／文化6改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積469㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0565","desc":"小谷城址南西隅の敷地中央に南面して建つ。木造平屋建、大和棟形式の切妻造桟瓦葺で、西寄りに式台玄関を構える。東端を広い土間とし、床上部に多数の部屋を配り、西北隅を奥座敷とする。重厚な軸部構成で造作も上質。堺市内で希少な江戸中期の大型民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009650"},{"id":"00009651","register_sub_id":"101","register_pk":"194647","name":"小谷家住宅正門","kana":"こたにけじゅうたくせいもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市南区豊田1612","lat":34.49335855,"lng":135.49770682,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積68㎡、廊下及び塀付","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0566","desc":"敷地西面に南北棟で建つ長屋門で、入母屋造本瓦葺である。中央南寄りを門口とし、鏡柱に板戸を開き、両側に潜戸を設ける。門の南に物見格子付の五畳、北に二室を並べ、北端室は落棟とする。外壁漆喰塗で腰を簓子下見板張とし、厳格な雰囲気を醸している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009651"},{"id":"00009653","register_sub_id":"101","register_pk":"194649","name":"小谷家住宅土塀","kana":"こたにけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市南区豊田1612","lat":34.49342128,"lng":135.49746221,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土塀、瓦葺及び銅板葺、総延長132m","structure_material":"土塀","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0568","desc":"敷地西側の道路沿いと、敷地入口から正門に向けてＳ字状に斜上する石畳沿いに湾曲して配された土塀。斜路北面を木造真壁造とするほかは土塀とし、総延長一三二メートルを測る。玉石積基礎に布石を伏せて土塀を築き、桟瓦葺とする。屋敷導入部に風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009653"},{"id":"00009652","register_sub_id":"101","register_pk":"194648","name":"小谷家住宅南門","kana":"こたにけじゅうたくみなみもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府堺市南区豊田1612","lat":34.49327289,"lng":135.49791621,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0567","desc":"敷地南辺に南面して建つ長屋門で、東側に土蔵が接続する。木造平屋建、切妻造本瓦葺で、東端を門口として板扉の両側に潜戸を吊り、西側に三室を並べる。外壁漆喰塗で腰を竪板張とし、要所に物見格子や武者窓を配して、城門のような重厚な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009652"},{"id":"00004781","register_sub_id":"101","register_pk":"105771","name":"小谷城郷土館瓦蔵・籾蔵","kana":"こたにじょうきょうどかんかわらぐら・もみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府堺市南区豊田1602-1","lat":34.49306662,"lng":135.49831717,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0314","desc":"門長屋の西面に接続し，北西に延びる。内部は東を籾蔵，西を瓦蔵とする。真壁造の平屋建で，切妻造の屋根は南を本瓦，北を桟瓦で葺き分ける。基礎は玉石積に切石を据え，南外壁は上部漆喰塗，下部を縦板張にする。門長屋とともに屋敷の外構をよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004781"},{"id":"00004779","register_sub_id":"101","register_pk":"105769","name":"小谷城郷土館主屋","kana":"こたにじょうきょうどかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市南区豊田1602-1","lat":34.493217,"lng":135.498428,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺一部瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0312","desc":"敷地のほぼ中央に南面して建つ。西の居室部と東の座敷部からなる平面で，各室は質の高いつくりである。居室部は切妻造，銅板葺，西の竈屋は低い瓦葺，座敷部は入母屋造，瓦葺で，南に式台玄関を突出する。変化に富む雄大な外観は，地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004779"},{"id":"00004783","register_sub_id":"101","register_pk":"105773","name":"小谷城郷土館土蔵","kana":"こたにじょうきょうどかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市南区豊田1602-1","lat":34.493015,"lng":135.498688,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0316","desc":"二番蔵の東面に接続し，表構えを整えている。もと米蔵で，現在は展示室に活用している。方形平面とした土蔵造の平屋建で，屋根は切妻造の置屋根式，本瓦葺とする。基礎は精緻な玉石積とし，内部は壁から桁・梁・天井まで漆喰で塗り固めた重厚なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004783"},{"id":"00004782","register_sub_id":"101","register_pk":"105772","name":"小谷城郷土館二番蔵","kana":"こたにじょうきょうどかんにばんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府堺市南区豊田1602-1","lat":34.49302376,"lng":135.49860076,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0315","desc":"門長屋の東面に接続する。ほぼ等分された内部は，東を米蔵，西を書庫とし，それぞれ北面に戸口を設ける。土蔵造の平屋建で，切妻造の屋根は南を本瓦，北を桟瓦とする。南外壁の下部は縦板張で，上に窓を設ける。門長屋とともに屋敷の表構えをよく整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004782"},{"id":"00004780","register_sub_id":"101","register_pk":"105770","name":"小谷城郷土館門長屋","kana":"こたにじょうきょうどかんもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市南区豊田1602-1","lat":34.493034,"lng":135.498444,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0313","desc":"主屋の南に建ち，門口とその東西に附属した部屋からなる。門口は中央に板扉を吊り，西に潜戸を設け，起りのある切妻造，本瓦葺の屋根を架ける。東西の部屋は塗屋造で，一段低い瓦葺とし，正面には櫛形窓を設ける。豪壮な屋敷に相応しい表構えを演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004780"},{"id":"00000064","register_sub_id":"101","register_pk":"101054","name":"コニシ株式会社（旧小西儀助商店）三階蔵","kana":"こにしかぶしきがいしゃ（きゅうこにしぎすけしょうてん）さんかいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町1-6","lat":34.68884276,"lng":135.50694083,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積45㎡","structure_material":"土蔵造3階建","registered":"1996.12.20(平成8.12.20)","register_no":"27 － 0004","desc":"敷地の背後に建つ３棟の土蔵のうち，東北部に位置する３階建の土蔵で，外観は１階部分を石張りとし，２・３階を白漆喰塗の大壁造とする。軒蛇腹は時代の特色を表す帯状のものになるが，妻側は２段のして変化を付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000064"},{"id":"00011741","register_sub_id":"101","register_pk":"210757","name":"小西朝陽館唐門及び脇塀","kana":"こにしちょうようかんからもんおよびわきべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.632982,"lng":135.503954,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"唐門 木造、檜皮葺（銅板仮葺）、間口1.8m 脇塀 木造、銅板葺、総延長8.9m","structure_material":"唐門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0678","desc":"竹田宮、東久邇宮の来訪にあわせて建てられたもの。京都山科の毘沙門堂中門の写しと伝える。檜皮葺（銅板仮葺）の向唐門で、本柱、控柱共に丸柱を用いる。扉は松に鷹の透し彫りをあしらう桟唐戸両開。脇塀も連子を入れた透塀で、精緻な技巧を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011741"},{"id":"00011738","register_sub_id":"101","register_pk":"210754","name":"小西朝陽館玄関","kana":"こにしちょうようかんげんかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.633019,"lng":135.503877,"geo_status":"db","era":"明治45年頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積21㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0674","desc":"主屋の東面南端に接続する。入母屋造の玄関の背後に廊下が取り付く。また、玄関から北には住居等に向かう廊下が取り付く。玄関は竹張天井、廊下は舟底天井とし、床面は磚の四半敷。廊下の主屋境では屋根を大きく反り上げる。禅宗寺院の趣を有する玄関である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011738"},{"id":"00011737","register_sub_id":"101","register_pk":"210753","name":"小西朝陽館御殿","kana":"こにしちょうようかんごてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.633084,"lng":135.50378,"geo_status":"db","era":"明治45年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋一部地階建、瓦葺、建築面積165㎡","structure_material":"木造平屋一部地階建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0673","desc":"皇族等の宿泊を意識して建てられた別荘。御殿は建物群の南寄りに位置し、南東の玄関から矩折れに濡縁を廻らし、北に一五畳広間、南に七畳半次の間を配す。広間は折上格天井に付書院・床脇を有する床構えなど豪壮な造り。北寄り階下には茶室を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011737"},{"id":"00011739","register_sub_id":"101","register_pk":"210755","name":"小西朝陽館新御殿","kana":"こにしちょうようかんしんごてん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.63334,"lng":135.503717,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0675","desc":"大正一一年の火災後、陸軍特別大演習に際して閑院宮若宮春仁王の宿泊のために再建されたもの。木造平屋建、入母屋造桟瓦葺で、軒先は銅板葺。内部は一五畳広間、八畳次の間を配し、椅子座を基本とするため内法が高い。天井は折上格天井で、シャンデリアを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011739"},{"id":"00011740","register_sub_id":"101","register_pk":"210756","name":"小西朝陽館月見台","kana":"こにしちょうようかんつきみだい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.633218,"lng":135.503707,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0676","desc":"御殿と新御殿をつなぐ渡り廊下と、懸造で張り出す部分からなる、切妻造桟瓦葺で庇は銅板葺。室内は四畳半一室の北側に床の間、床脇が付く。渡廊下は延長一二・八メートルで、西面は高塀となり、天井は緩やかなヴォールト状に設え、南半部の床は杉材を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011740"},{"id":"00011742","register_sub_id":"101","register_pk":"210758","name":"小西朝陽館門及び御所塀","kana":"こにしちょうようかんもんおよびごしょべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区橋本町13-2他","lat":34.632945,"lng":135.504025,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"門 木造、銅板葺、間口1.6m 御所塀 土塀、瓦葺、総延長37m","structure_material":"門 木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0678","desc":"敷地内にあって、唐門へと導く築地塀。東寄りに門口を開く。基礎は切石を高く積み、屋根は本瓦葺。軒丸瓦には家紋の三ツ追い柏、棟側面の練込瓦には小西家家業の薬のブランドにちなんだ力士を配す。別荘が建ち並んだ当地のかつての景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011742"},{"id":"00007262","register_sub_id":"101","register_pk":"108244","name":"古畑家住宅米蔵","kana":"こばたけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.9613538,"lng":135.60542466,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造平屋建、瓦葺、建築面積49㎡","structure_material":"土蔵造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0491","desc":"敷地の南東隅に建つ。桁行１０ｍ梁間４．９ｍ、土蔵造平屋建、切妻造桟瓦葺。外壁は腰竪板張の白漆喰仕上げ。主屋側の北面西寄りに出入口を設け、庇を付けた小窓を開ける。内部は２室に分け、土壁仕上げ。広大な屋敷地の角地に建つ大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007262"},{"id":"00007256","register_sub_id":"101","register_pk":"108238","name":"古畑家住宅主屋","kana":"こばたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.96158124,"lng":135.60533504,"geo_status":"db","era":"大正期／昭和31頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積261㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0485","desc":"山間部の傾斜地に敷地を占め、中央に主屋が南面して建つ。桁行１７ｍ梁間１３ｍ規模で、木造つし２階建。入母屋造桟瓦葺で、正面上部に虫籠窓を穿つ。奥まった玄関を東寄りに設け、西側に座敷などを食違いに配する。大型の近代農家建築で、山村景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007256"},{"id":"00007261","register_sub_id":"101","register_pk":"108243","name":"古畑家住宅新蔵","kana":"こばたけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.96172314,"lng":135.60541342,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0490","desc":"西の蔵北面に建つ。桁行５．４ｍ梁間３．９ｍ規模、土蔵造２階建で、切妻造桟瓦葺の置屋根とする。外壁は腰を竪板張とし、置屋根の軒まで白漆喰で塗り込める。西面は西の蔵と連続して石垣上に建つが、棟高がやや高く、１階にも窓を穿ち、外観に変化をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007261"},{"id":"00007263","register_sub_id":"101","register_pk":"108245","name":"古畑家住宅長屋門","kana":"こばたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.961411,"lng":135.605469,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0492","desc":"主屋の東南に建つ木造平屋建。屋根は桟瓦葺で、南を入母屋造、北端を東二の蔵に接続する。北寄りを門口とし、両開の板戸を吊り、脇に潜戸を開く。また南寄りの１間は板敷の男衆部屋とする。通りに面して並び建つ土蔵群とともに、重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007263"},{"id":"00007260","register_sub_id":"101","register_pk":"108242","name":"古畑家住宅西の蔵","kana":"こばたけじゅうたくにしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.96167152,"lng":135.60535724,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0489","desc":"主屋北面に接続し、南北棟で石垣上に建つ。桁行４．１ｍ梁間３．９ｍ規模、土蔵造２階建、切妻造桟瓦葺。外壁は白漆喰仕上げで、腰を竪板張とする。屋根は他の土蔵同様、置屋根の軒まわりも外壁と一体的に漆喰で塗り込める。内部は横板嵌とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007260"},{"id":"00007257","register_sub_id":"101","register_pk":"108239","name":"古畑家住宅離れ","kana":"こばたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷24","lat":34.961452,"lng":135.605225,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0486","desc":"敷地の南西、主屋の向かいに建つ。桁行１０ｍ梁間７．０ｍ、木造平屋建、入母屋造桟瓦葺で、南北２列に室を配し、いずれも東から、土間、次の間、主室とする。南列の主室は座敷飾りを備え、北列では数寄屋風にまとめる。近代の大規模農家における離れ座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007257"},{"id":"00007258","register_sub_id":"101","register_pk":"108240","name":"古畑家住宅東一の蔵","kana":"こばたけじゅうたくひがしいちのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.961533,"lng":135.60553,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0487","desc":"敷地東辺の中央、通りに面して建つ。桁行４．０ｍ梁間３．８ｍ規模、土蔵造２階建とする。切妻造桟瓦葺の置屋根とし、軒まわりまで塗り込める。外壁は腰竪板張の白漆喰仕上げ。敷地東辺に並び建つ東二の蔵などと統一的な意匠になり、屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007258"},{"id":"00007259","register_sub_id":"101","register_pk":"108241","name":"古畑家住宅東二の蔵","kana":"こばたけじゅうたくひがしにのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府高槻市大字中畑小字清谷23","lat":34.961472,"lng":135.60548638,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0488","desc":"敷地の東辺、長屋門と東一の蔵の間に建つ。桁行５．８ｍ梁間４．２ｍ規模、土蔵造２階建、切妻造桟瓦葺。屋根は置屋根形式であるが、置屋根の軒も外壁と一連で漆喰で塗り込める。外壁は白漆喰仕上げで、腰竪板張。長屋門と接し、風格ある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007259"},{"id":"00009649","register_sub_id":"101","register_pk":"194645","name":"小森家住宅表門","kana":"こもりけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区谷町6-4","lat":34.67520205,"lng":135.51258365,"geo_status":"db","era":"大正13頃","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右塀付","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0564","desc":"敷地西辺北寄りで、土蔵に接続する。間口二・四メートル、一間薬医門、切妻造桟瓦葺で、南北に板塀をのばし、北側に潜戸を開く。軸部は五平の本柱頂部を冠木で固めて梁を架け、軒桁を渡し、本柱に竪板張の板戸を両開きに吊る。端正なつくりの表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009649"},{"id":"00009647","register_sub_id":"101","register_pk":"194643","name":"小森家住宅主屋","kana":"こもりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区谷町6-4","lat":34.67512828,"lng":135.51270263,"geo_status":"db","era":"大正13頃／昭和20・平成15改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺及び銅板葺、建築面積235㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0562","desc":"北西角地の敷地中央に建つ。寄棟造桟瓦葺で、北面に大振りな車寄を構え、北東に台所を張出す。一階は玄関ホールの四方に部屋を配し、二階は座敷三室を東西に並べ、三方に縁を廻らせてガラス窓をたて、柱上に舟肘木を載せる。開放的で上質なつくりの近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009647"},{"id":"00009648","register_sub_id":"101","register_pk":"194644","name":"小森家住宅土蔵","kana":"こもりけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市中央区谷町6-4","lat":34.67523774,"lng":135.51261697,"geo_status":"db","era":"江戸後期／昭和20改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"27 － 0563","desc":"敷地の北西角に東西棟で建ち、桁行一二メートル梁間四・二メートル、土蔵造二階建、切妻造本瓦葺である。南面と西面を戸口とし、戦中の改修により窓を広く開ける。外壁は漆喰塗で腰板を高く張る。戦災などにより変容著しい界隈において、希少な江戸期の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009648"},{"id":"00002654","register_sub_id":"101","register_pk":"103644","name":"兒山家住宅隠居所","kana":"こやまけじゅうたくいんきょじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.514996,"lng":135.522202,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0175","desc":"主屋の西，屋敷西側の通りに面して建つ。平屋建，南妻入母屋造，北妻切妻造(庇付)，本瓦葺で，中央に通用門を開き，その北を隠居所，南を馬小屋としていた。簡素な造りだが，隠居所表側に出格子窓を設けて長屋門風とするなど，屋敷の西面にあって目立つ施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002654"},{"id":"00002650","register_sub_id":"101","register_pk":"103640","name":"兒山家住宅内蔵","kana":"こやまけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.515121,"lng":135.522446,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0171","desc":"家財を収容する施設で，主屋の背後に取り合いを介して接続する。２階建，切妻造，本瓦葺の土蔵で，外部は漆喰仕上，腰を竪板張とする。装飾要素は一切用いず簡素な造りだが，破風，垂木等を塗込めた丁寧な仕事になり，立ちの高い平明な姿は目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002650"},{"id":"00002647","register_sub_id":"101","register_pk":"103637","name":"兒山家住宅座敷","kana":"こやまけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.51497741,"lng":135.522522,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0168","desc":"主屋の東に接続。入母屋造，本瓦葺で，南・東に矩折れに廻る縁部分は錣葺とする。表側は主室，次の間を並べ，背後に茶室，仏間，化粧の間を配す。角柱で長押を廻し，主室に床，違棚，付書院を設け格式を備えるが，木割が細く天井高も押さえ瀟洒な意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002647"},{"id":"00002646","register_sub_id":"101","register_pk":"103636","name":"兒山家住宅主屋","kana":"こやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.51498292,"lng":135.52241131,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積254㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0167","desc":"市内村邑部にある豪農の屋敷。敷地中央に南面して建つ主屋は，２階建，入母屋造，本瓦葺で，西半を土間，東半を６間取りの居室部とする。正面に虫籠窓をあけつし２階風に見せるが，登梁による小屋組で本２階とする。入母屋を重ねた屋根等，重厚な外観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002646"},{"id":"00002652","register_sub_id":"101","register_pk":"103642","name":"兒山家住宅外蔵","kana":"こやまけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.515133,"lng":135.522186,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0173","desc":"納屋の西方，敷地の北西隅に建つ。平屋建，切妻造，本瓦葺の土蔵で，外部は漆喰塗，腰を竪板張とする。小規模ながら内蔵とは異なり軒廻り，螻蛄羽を一連に塗り込めた本格的な造りで，敷地北西隅の目立つ位置に建ち，屋敷構えの構成要素として欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002652"},{"id":"00002655","register_sub_id":"101","register_pk":"103645","name":"兒山家住宅土塀","kana":"こやまけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.5151155,"lng":135.5227728,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、延長105m","structure_material":"木造","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0176","desc":"屋敷東部の庭園の南・東・北及び内蔵・納屋間は内外とも塗り込めた土塀の形式で，屋敷南西隅，門長屋・隠居所間に矩折れに廻る塀は，柱・腕木・出桁を表し上半漆喰塗・下半竪板張とする。外面する隣接建物とともに，屋敷構えの構成要素として欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002655"},{"id":"00002649","register_sub_id":"101","register_pk":"103639","name":"兒山家住宅取り合い","kana":"こやまけじゅうたくとりあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.515068,"lng":135.522415,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積47㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0170","desc":"主屋の背後，北方の内蔵との間の接続部分。南半を２階建，北半を平屋とし，屋根は２階建部分が切妻造で下屋を付し，平屋部分は両下で，いずれも本瓦葺とする。平屋部分の西に湯殿・便所を張り出す。簡素な付属施設だが，主屋と一連の堅固で上質な造りとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002649"},{"id":"00002651","register_sub_id":"101","register_pk":"103641","name":"兒山家住宅納屋","kana":"こやまけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.51512626,"lng":135.522308,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0172","desc":"主屋の北，内蔵の西に隣接して建つ。平屋建，切妻造，桟瓦葺で，前面に腕木で持ち出した出の大きい庇を一段下げて付ける。外部は漆喰塗，腰竪板張で，内部は桁行きに３室に仕切り，漬物や柴，農耕具を収納していた。屋敷構えの構成要素として欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002651"},{"id":"00002648","register_sub_id":"101","register_pk":"103638","name":"兒山家住宅離れ","kana":"こやまけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.51503302,"lng":135.522614,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0169","desc":"座敷の東面北端に突出した寄棟造，桟瓦葺の付属棟で，座敷の一部改造にともなって増築された。３畳大の小室の３方に縁を廻し，北東には湯殿と便所を張り出して設ける。小規模で簡素な建物だが，座敷に不可欠な施設であり，南の庭園に面して瀟洒な外観を造る","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002648"},{"id":"00002653","register_sub_id":"101","register_pk":"103643","name":"兒山家住宅門長屋","kana":"こやまけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市中区陶器北1404","lat":34.514851,"lng":135.522385,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"27 － 0174","desc":"屋敷正面やや西寄りに建つ。平屋建，入母屋造，本瓦葺で，正面を黒漆喰塗，他を白漆喰塗とし，腰を竪板張とする。ほぼ中央に門を開き，その東西を現在は納屋とする。桁行きに長く表側に横連子窓を並べた長屋門形式で，屋敷の正面構えの中心となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002653"},{"id":"00003115","register_sub_id":"101","register_pk":"104105","name":"堺市茶室黄梅庵","kana":"さかいしちゃしつおうばいあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区百舌鳥夕雲町2丁大仙公園内","lat":34.55956184,"lng":135.48427519,"geo_status":"db","era":"江戸中期／昭和23・55移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0204","desc":"橿原市今井町の豊田家から小田原の松永耳庵邸に移され，再度現在地に移築保存された。８畳の広間に３畳下座床の茶室が接続し，裏側に勝手・水屋等が付属する。広間・茶室とも正当な草庵の意匠・技法を踏襲しつつ，平面構成や細部に独特の創意と造形をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003115"},{"id":"00003116","register_sub_id":"101","register_pk":"104106","name":"堺市茶室伸庵","kana":"さかいしちゃしつしんあん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市堺区百舌鳥夕雲町2丁大仙公園内","lat":34.559727,"lng":135.484116,"geo_status":"db","era":"昭和4／昭和55移築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積288㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0205","desc":"東京芝にあった仰木魯堂設計になる建築。玄関棟，広間・茶室棟，２階建座敷棟が中央の中庭を囲んで建ち並ぶ。面皮材，丸太材，栂角材等多様な材を用い，柱間も田舎間，中京間，京間を使い分けるなど，古典的手法に依りながら随所に近代らしい特徴がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003116"},{"id":"00001438","register_sub_id":"101","register_pk":"102428","name":"阪之上家住宅蔵","kana":"さかのうえけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町5-594","lat":34.53871107,"lng":135.44522648,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0082","desc":"離れ座敷の東面に接続する内蔵で，東隣地の境界近くに建つ。南北棟，切妻屋根，平入，桁行３間，梁間２間規模の標準的な造りになる２階建土蔵であるが，屋根を本瓦で葺く。離れ座敷と一体となって，邸宅の構えの一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001438"},{"id":"00001440","register_sub_id":"101","register_pk":"102430","name":"阪之上家住宅外塀","kana":"さかのうえけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町5-594","lat":34.53885713,"lng":135.44503632,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"延長19m、門柱含む","structure_material":"延長19m","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0084","desc":"宅地の北西端から洋館北西端につながる外塀で，洋館寄りに宅地側に退いて石造の門柱を建てる。洋館西面が街路に接しているため，洋館の柱型意匠に合わせたバットレスを街路側に見せている点に特徴がある。住宅地景観の構成要素としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001440"},{"id":"00001437","register_sub_id":"101","register_pk":"102427","name":"阪之上家住宅離れ座敷","kana":"さかのうえけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町5-594","lat":34.53871024,"lng":135.44514804,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0081","desc":"洋館の南東方に建つ桟瓦葺，寄棟屋根，平屋建の離れ座敷棟。南，西，北の３面に軒先を銅板で葺いた瓦葺の庇を回し，南東に茶室をはりだす。座敷部はつし２階風の外観を採り，内部は床・棚・書院付きの座敷を中心に上質な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001437"},{"id":"00001436","register_sub_id":"101","register_pk":"102426","name":"阪之上家住宅洋館","kana":"さかのうえけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町5-594","lat":34.53880628,"lng":135.44504348,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造2階建、建築面積37㎡","structure_material":"煉瓦造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0080","desc":"大正７年頃から浜寺土地株式会社が分譲した海浜別荘地に所在する住宅建築の独立型洋館。浜寺土地株式会社が計画して未実施に終わった浜寺ホテルの設計図の一部を採って建築されたと伝える。柱型をパラペットまで通したファサード構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001436"},{"id":"00001439","register_sub_id":"101","register_pk":"102429","name":"阪之上家住宅渡廊下","kana":"さかのうえけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府堺市西区浜寺昭和町5-594","lat":34.53877769,"lng":135.44511162,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、建築面積6.5㎡","structure_material":"木造","registered":"1999.11.18(平成11.11.18)","register_no":"27 － 0083","desc":"阪之上家の敷地は，南と西が街路に接した５３ｍ×２６ｍの南北に長い角地で，ほぼ中央に離れ座敷が，北寄りに主屋が建つ。主屋は近年改築されたが，かっての主屋と離れ座敷を結ぶ連絡通路は現存し，洋館と中庭部との結界をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001439"},{"id":"00002154","register_sub_id":"101","register_pk":"103144","name":"佐竹ガラス主屋","kana":"さたけがらすしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.50250773,"lng":135.43833755,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建、瓦葺、建築面積275㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0135","desc":"市中心部に位置する。敷地内に住居建築と工場が混在し，木造２階建，入母屋造の主屋は，敷地南端の角地に位置する。白漆喰と繊細な縦格子からなる１階正面と，平側に文様をあしらった虫籠窓を穿つ黒漆喰壁面からなる２階部で，外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002154"},{"id":"00002159","register_sub_id":"101","register_pk":"103149","name":"佐竹ガラス鎮守社","kana":"さたけがらすちんじゅしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-11-30","lat":34.50272866,"lng":135.43793104,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積2㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"27 － 0140","desc":"切石積基壇上に建つ銅板葺の一間社流造社殿。身舎・向拝とも角柱を用い，組物は入れずに桁を直接柱で受ける。軒は一軒疎垂木で，向拝に弓状の虹梁を入れ，中備蟇股とする。小規模な社殿で簡素なつくりだが，屋敷角地を占める構成要素として欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002159"},{"id":"00005473","register_sub_id":"101","register_pk":"106461","name":"佐野家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町3-21-15","lat":34.629093,"lng":135.51276417,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2006.03.27(平成18.03.27)","register_no":"27 － 0360","desc":"街路に北面する木造２階建で，間口３間半の本宅と間口２間半の貸家に一体に切妻屋根をかける。貸家１階には土蔵を造り込む。外壁はモルタル塗りで，軒蛇腹をつけ，本宅の両脇に袖卯建を設ける。１階正面は出格子。郊外の通りに面して建つ町家の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005473"},{"id":"00000800","register_sub_id":"101","register_pk":"101790","name":"澤村家住宅","kana":"さわむらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市桜ヶ丘2-6-3","lat":34.82309044,"lng":135.45866751,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，瓦葺，建築面積66㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"27 － 0047","desc":"日本建築協会住宅改造博の会場に建てられた洋風住宅。同協会主催第１回改良住宅設計図案懸賞募集「市街地における一戸建住案」において第１等当選をはたした谷本甲子三の案を実現したもの。Ｌ字形の平面とアーチ窓を持つ応接室兼書斎が外観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000800"},{"id":"00015203","register_sub_id":"101","register_pk":"530627","name":"サントリー天満寮（旧久徳家住宅）主屋","kana":"さんとりーてんまりょう（きゅうひさとくけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神橋二丁目49","lat":34.696925,"lng":135.51316944,"geo_status":"db","era":"昭和14年／昭和中期・令和6年改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積147㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"27 - 0936","desc":"大阪天満宮境内北側に位置し、南面して建つ大塀造の住宅主屋。二階建切妻造桟瓦葺の起り屋根で妻壁の一階を板張、二階を漆喰塗の大壁とする。各階南側に座敷を設け、二階座敷は床や付書院を備え、天井板など良材用い、南縁を介し天満宮を望む良質な和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015203"},{"id":"00015204","register_sub_id":"101","register_pk":"530628","name":"サントリー天満寮（旧久徳家住宅）門及び塀","kana":"さんとりーてんまりょう（きゅうひさとくけじゅうたく）もんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神橋二丁目49","lat":34.69681667,"lng":135.51317222,"geo_status":"db","era":"昭和14年頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"門 木造、瓦葺、間口1.6m、潜戸付 塀 木造、瓦葺、総延長18m","structure_material":"門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"27 - 0937","desc":"主屋の南に建つ門とその両脇に続く塀。切石積二段を基礎上に建つ塀は、総延長18メートル、高さ３・１メートル、外壁浅黄色の土壁とし、高く竪板を張る。東寄りに開く門口には桟瓦葺腕木庇を付し、格子戸を建てる。大塀造町家の正面を整える瀟洒な門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015204"},{"id":"00001290","register_sub_id":"101","register_pk":"102280","name":"篠崎家住宅","kana":"しのざきけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市桜ケ丘二丁目137","lat":34.82422217,"lng":135.45938576,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造２階建，スレート葺，建築面積70㎡","structure_material":"木造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"27 － 0074","desc":"大正住宅改造博覧会において日本建築協会の出品住宅としてつくられたもので，碓井英隆の懸賞募集案を改良したもの。三方を道に面した敷地に建つ洋風住宅で，三面に切妻屋根をみせた外観と広間を中心とした間取りに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001290"},{"id":"00010213","register_sub_id":"101","register_pk":"198046","name":"嶋田家住宅大門","kana":"しまだけじゅうたくおおもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市天美東8-627","lat":34.587267,"lng":135.534344,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0610","desc":"敷地東面南寄りに位置し米蔵と蔵の間に建つ。間口七・〇メートル、両下造本瓦葺で、両端間を物入とする。中央間を門口として舟肘木で梁を受け、本柱内にケヤキ扉を吊り、両脇に潜戸を開く。物入は表側を簓子下見板張とする。雄大かつ重厚で風格を備えた表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010213"},{"id":"00010211","register_sub_id":"101","register_pk":"198044","name":"嶋田家住宅奥座敷棟","kana":"しまだけじゅうたくおくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府松原市天美東8-627","lat":34.587371,"lng":135.534006,"geo_status":"db","era":"明治20頃","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0608","desc":"主屋西側に接続する入母屋造桟瓦葺の建物。十畳主室と七畳半の次の間を東西に並べ、南北に縁を通し、次の間南に三畳半茶室を張出す。主室に座敷飾を備え、室境に山並みを模した欄間を飾る。竹の落掛など、数寄屋を加味し、洗練された意匠の離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010211"},{"id":"00010210","register_sub_id":"101","register_pk":"198043","name":"嶋田家住宅玄関書院","kana":"しまだけじゅうたくげんかんしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市天美東8-627","lat":34.587267,"lng":135.53411,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0607","desc":"南面する主屋の前面に鞘の間を介して建つ。東面する式台玄関は正面小壁を円弧状に切取り、格子をいれて優美な外観とする。南側の座敷はトコに丸窓を開け、落掛を斜めに振るなど斬新な意匠の数寄屋である。独立した玄関棟で、大阪近郊の近代邸宅の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010210"},{"id":"00010212","register_sub_id":"101","register_pk":"198045","name":"嶋田家住宅道具蔵","kana":"しまだけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市天美東8-627","lat":34.587443,"lng":135.533972,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0609","desc":"敷地北西隅、奥座敷棟の北側に南北棟で建つ。土蔵造二階建、桁行五・二メートル梁間四・三メートル、切妻造本瓦葺で、躯体は校木を積む井籠組とする。外壁は軒裏まで塗込め、腰高に竪板を張る。東面に戸口を開いて下屋を設ける。当地方には珍しい構造の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010212"},{"id":"00001932","register_sub_id":"101","register_pk":"102922","name":"樟徳館主屋","kana":"しょうとくかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.65361807,"lng":135.578186,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積1169㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0113","desc":"樟蔭学園の創立者で，大阪・長堀で材木商を営んだ森平蔵の私邸。入母屋造の玄関車寄を中央にし，左手に平屋建の応接間棟，右手に２階建の居室棟をバランスよく配す。自ら木取りした良材をふんだんに用い，和洋折衷の室内意匠でまとめられた近代和風邸宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001932"},{"id":"00001934","register_sub_id":"101","register_pk":"102924","name":"樟徳館鎮守社","kana":"しょうとくかんちんじゅしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.653839,"lng":135.577942,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0115","desc":"敷地の西北方の奥，蔵の南側に位置する。屋敷神として設置され，縁石で間口６．７ｍ，奥行４．７ｍの区画をなし，その中央部に花崗石で見かけ３段の基壇を造り，木造，銅板葺，八幡造の社殿を置く。宇佐神宮本殿を模したもので，「八幡さん」と呼ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001934"},{"id":"00001933","register_sub_id":"101","register_pk":"102923","name":"樟徳館土蔵","kana":"しょうとくかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.65389776,"lng":135.57803538,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積133㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0114","desc":"敷地の西北方隅に建つ。桁行５間，梁行２間半規模の東西棟，切妻造，本瓦葺の２階建土蔵を東西に配置し，その間を棟を落とした桟瓦葺屋根で繋ぎ，南面に下屋を差し掛けて蔵前をとる。取合いを含めて桁行方向１３間と屋敷構えに相応しい規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001933"},{"id":"00001936","register_sub_id":"101","register_pk":"102926","name":"樟徳館東塀","kana":"しょうとくかんひがしべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.65348682,"lng":135.57847388,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、延長24m","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0117","desc":"門北端から長瀬川沿いに北方に向かう延長約２４ｍの屋根塀。土台建の真壁造で，腰を板張，上部を土壁とし，頂部に桟瓦葺の小屋根を載せる。長瀬川沿いの道路との間に植込みをなし，門と相まってのびやかな表構えをつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001936"},{"id":"00001937","register_sub_id":"101","register_pk":"102927","name":"樟徳館南塀","kana":"しょうとくかんみなみべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.65332007,"lng":135.57818803,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、延長70m","structure_material":"木造","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0118","desc":"門南端から敷地東南隅で折れ曲がり，敷地南辺を西に向かう延長約７０ｍの屋根塀。東塀と同様な造りで，土台建の真壁造，腰部を板張，上部を土壁とし頂部に桟瓦葺の小屋根を頂く。前面には木製の矢来柵を効果的に置いて趣ある横道空間をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001937"},{"id":"00001935","register_sub_id":"101","register_pk":"102925","name":"樟徳館門","kana":"しょうとくかんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市菱屋西2-4-12","lat":34.65337714,"lng":135.57842855,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造薬医門、瓦葺、間口3.2m","structure_material":"木造薬医門","registered":"2000.10.18(平成12.10.18)","register_no":"27 － 0116","desc":"長瀬川沿いの敷地東辺の南寄りの位置に，道路からやや奥にひいて建つ。間口約３．１５ｍの一間薬医門で，左右にコの字型に袖塀を従え，両脇に潜戸を開ける。屋根に緩やかなムクリをつけ，門扉を１枚板とするなど上質な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001935"},{"id":"00004372","register_sub_id":"101","register_pk":"105362","name":"末吉家住宅主屋","kana":"すえよしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-3-5","lat":34.62625183,"lng":135.55259488,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積320㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0300","desc":"豪商の本宅。通りに北面する木造平屋建で，桁行５間梁間４間半の表に庇がつく。切妻屋根は本瓦葺，外壁は土壁で腰を縦羽目板張とする。東妻に式台玄関と内玄関を設け，中廊下を挟んで出格子窓のある格子の間，座敷など４室を配す。南背面に台所と座敷が付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004372"},{"id":"00004373","register_sub_id":"101","register_pk":"105363","name":"末吉家住宅西蔵","kana":"すえよしけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-3-5","lat":34.626297,"lng":135.552307,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積77㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0301","desc":"敷地の北西角，主屋の西に位置する南北棟の土蔵造２階建である。桁行５間梁間４間の切妻造，本瓦葺で，凝灰岩切石３段の基礎上に建つ。外壁は白漆喰塗で腰を縦羽目板張とする。庭側の東面に両開き土戸の戸口を設け，２階両妻に二つずつ庇付きの窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004373"},{"id":"00004375","register_sub_id":"101","register_pk":"105365","name":"末吉家住宅塀","kana":"すえよしけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-3-5","lat":34.62633609,"lng":135.5524061,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、延長16m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0303","desc":"敷地北辺を限る高塀。門から主屋間４ｍ，主屋から西蔵間１１．６ｍを繋ぐ。土壁の腰を縦羽目板張とし，主屋の西に開き戸を１箇所と虫籠窓２箇所を設ける。屋根は桟瓦葺とするが，門及び主屋の北面とともに敷地北辺に連続感のある景観を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004375"},{"id":"00004374","register_sub_id":"101","register_pk":"105364","name":"末吉家住宅門","kana":"すえよしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市平野区平野上町2-3-5","lat":34.62632066,"lng":135.55272933,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積13㎡、袖壁付","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"27 － 0302","desc":"敷地北辺東端の表門。桁行２間梁間１間半で，北から半間通りに門扉を釣込み，東に潜戸を設ける。屋根は切妻造，本瓦葺で，東に１間延びた出格子付の塀も一連に葺く。外壁は土壁で腰を縦羽目板張とし，主屋との間の高塀とともに連続感のある景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004374"},{"id":"00002070","register_sub_id":"101","register_pk":"103060","name":"杉田家住宅蔵","kana":"すぎたけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府富田林市本町5-13","lat":34.50261466,"lng":135.59907976,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0131","desc":"木造，２階建，切妻造，桟瓦葺の建物で，敷地の南端部に位置し，主屋の奥に蔵前を介して接続する。白壁で大きな軒蛇腹を持つ丁寧な仕事になる伝統的な土蔵造で，立ちの高い外観は洋風の主屋と好対照をなし，屋敷構えを整える重要な要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002070"},{"id":"00002069","register_sub_id":"101","register_pk":"103059","name":"杉田家住宅主屋","kana":"すぎたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府富田林市本町5-13","lat":34.50273817,"lng":135.59905048,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0130","desc":"木造，一部コンクリート造，２階建，寄棟造，瓦葺で，洋風の外観で玄関ポーチやその脇に洋室を配すが，その奥や二階には和室を造る。アールデコ風の玄関ポーチや室内各室など洗練された意匠になり，和洋の意匠を巧みに融合した特徴ある住宅建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002069"},{"id":"00003574","register_sub_id":"101","register_pk":"104564","name":"大道旧山本家住宅蔵","kana":"だいどうきゅうやまもとけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府南河内郡太子町山田1797","lat":34.51654569,"lng":135.65526672,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0267","desc":"難波津と飛鳥を結ぶ「大道」竹内街道沿いに位置する敷地中央の大和棟形式の主屋の東方に東西棟で建つ。桁行５間，梁間２間規模，切妻造，桟瓦葺の平入２階建土蔵で，腰を板張とし，上部の漆喰壁に持送付きの大きな水切瓦を廻している点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003574"},{"id":"00002963","register_sub_id":"101","register_pk":"103953","name":"大道旧山本家住宅主屋","kana":"だいどうきゅうやまもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府南河内郡太子町山田1797","lat":34.516521,"lng":135.655228,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺一部瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0201","desc":"堺と大和を結ぶ竹内街道に面して屋敷を構える旧家。主屋は桁行７間梁間５間で北西を正面とし，差鴨居を用いた構造手法などから江戸末期の建築と推定される。切妻造で中央茅葺，両側を本瓦葺としたいわゆる大和棟で，旧街道に相応しい景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002963"},{"id":"00002964","register_sub_id":"101","register_pk":"103954","name":"大道旧山本家住宅離れ","kana":"だいどうきゅうやまもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府南河内郡太子町山田1797","lat":34.516586,"lng":135.655075,"geo_status":"db","era":"大正1","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡、渡廊下付","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0202","desc":"堺と大和を結ぶ竹内街道に面して屋敷を構える旧家。離れは主屋前方にあって，渡り廊下で結ばれ，棟札より大正元年の建立と判明する。入母屋造，四周庇付の桟瓦葺で，８畳の座敷には床・棚・付書院を備えており，規模は小さいが丁寧なつくりの書院造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002964"},{"id":"00006874","register_sub_id":"101","register_pk":"107856","name":"高田家住宅米蔵","kana":"たかだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府八尾市久宝寺5-47-1他","lat":34.62700303,"lng":135.58678787,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造平屋建、瓦葺一部金属板葺、建築面積88㎡","structure_material":"土蔵造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"27 － 0450","desc":"主屋の東南方、側道に面して南北棟で建つ。切妻造桟瓦葺、桁行９．５ｍ梁間５．８ｍの土蔵造平屋建で、西面に奥行２．９ｍの蔵前を付ける。内部は桁行中央で南北２室に分け、両室とも蔵前に扉口、背面に窓を開ける。床は板敷で、小屋をトラス組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006874"},{"id":"00006873","register_sub_id":"101","register_pk":"107855","name":"高田家住宅主屋","kana":"たかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市久宝寺5-47-1他","lat":34.62711,"lng":135.58651009,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積151㎡、塀付","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"27 － 0449","desc":"旧久宝寺村の街路に北面して建つ。切妻造平入桟瓦葺。桁行６間梁間３間のつし２階建上屋に、正・背面に下屋庇、西側面に落棟を付ける。正面外観は１階に出格子を設け、つし２階は小さく虫籠窓を開ける大壁造とし、寺内町の落ち着いた町並み景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006873"},{"id":"00000359","register_sub_id":"101","register_pk":"101349","name":"高橋家住宅","kana":"たかはしけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市箕面1-2-25","lat":34.83450742,"lng":135.46702975,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建，スレート葺，建築面積330㎡","structure_material":"木造2階建","registered":"1997.11.05(平成9.11.05)","register_no":"27 － 0026","desc":"明治後期から宅地開発が行われた箕面川に面した地に建つ洋館。出窓をはじめ突出部を多くつくり，急勾配の屋根や縦長の窓を持つ等本格的な洋風の意匠になる。明治末年から大正期に大規模な邸宅において多くつくられた接客用洋館の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000359"},{"id":"00016557","register_sub_id":"101","register_pk":"574919","name":"高橋家住宅書斎及び渡り廊下","kana":"たかはしけじゅうたくしょさいおよびわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市箕面一丁目2-25","lat":34.83454389,"lng":135.467215,"geo_status":"db","era":"大正8年頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、スレート葺一部瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0965","desc":"箕面川に面した敷地に建つ洋館に付属する書斎及び渡り廊下。書斎は半切妻造スレート葺東西棟で西・南に出窓、北に渡り廊下を設ける。書斎は一室の洋間で、朝顔などをモチーフとしたステンドグラスを飾り、洋館と共通する外観意匠で大規模邸宅の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016557"},{"id":"00016412","register_sub_id":"101","register_pk":"536479","name":"瀧山家住宅（旧谷口家住宅）主屋","kana":"たきやまけじゅうたく（きゅうたにぐちけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区大領一丁目13-6","lat":34.61985278,"lng":135.50759722,"geo_status":"db","era":"昭和8年／昭和39年増築、同50年頃・令和3年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"27 - 0951","desc":"万代池公園東方の住宅地に建つ教員の旧宅。２階建桟瓦葺で外壁はクリーム色のモルタル仕上、腰をタイル貼とする。外観はスパニッシュ様式を基調とし、玄関廻りや応接室に泰山タイルやアール・ヌーヴォー調のステンドグラスを用い、意匠的な特徴をみせる主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016412"},{"id":"00003452","register_sub_id":"101","register_pk":"104442","name":"竹本家住宅主屋","kana":"たけもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市西町17-11","lat":34.44976004,"lng":135.355896,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積169㎡","structure_material":"木造平屋一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0245","desc":"紀州街道から西に１本入った筋にある食い違いの交差点に面する住宅。間口７間規模で，正面に出格子や与力窓などを配し，東側面の木太い無双窓から貝塚御坊願泉寺を望むつくりとする。前面が比較的閉鎖的で，商家ではなく，武家か寺役人の住宅と見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003452"},{"id":"00003280","register_sub_id":"101","register_pk":"104270","name":"竹本家住宅西主屋","kana":"たけもとけじゅうたくにししゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市北町18-1","lat":34.44974892,"lng":135.3575734,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積161㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0225","desc":"堀之町筋北側にある町家で，昭和初期まで当地特産の黄楊櫛を製作していた。間口３間半で東側を通り土間とし，奥行きに３部屋を並べる伝統的な平面であるが，塗籠めた前面の建ちが高く総２階であるなど，新しい要素が見える。貝塚における近代町家の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003280"},{"id":"00003281","register_sub_id":"101","register_pk":"104271","name":"竹本家住宅東主屋","kana":"たけもとけじゅうたくひがししゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町18-1","lat":34.44972302,"lng":135.35763619,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0226","desc":"西主屋東側に接して建つ桁行２間半の小規模な町家で，西主屋と続きで使われる。地盤は約６０センチ高いが，建物の建ちが低く，屋根は西主屋よりも低く納まる。２階中央に洋室を造るなど改造も多いが，なお小規模な江戸期の町家の様子を偲ぶことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003281"},{"id":"00016559","register_sub_id":"101","register_pk":"574921","name":"田中家住宅乾蔵","kana":"たなかけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府四條畷市大字逢阪213","lat":34.73836111,"lng":135.67366667,"geo_status":"db","era":"大正6年／大正後期増築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0967","desc":"主屋の北西に接続する内蔵。南面して建つ二階建切妻造平入、置屋根形式の桟瓦葺で、外壁は漆喰塗仕上とし、腰は竪羽目板を高く張る。戸口には主屋との間に畳敷の部屋を設けて蔵前とし、南東に廊下を通す。妻に屋号を掲げ、集落の歴史的な景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016559"},{"id":"00006687","register_sub_id":"101","register_pk":"107670","name":"田中家住宅表門","kana":"たなかけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51441958,"lng":135.41969978,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0445","desc":"主屋の東方、旧紀州街道沿いに建つ。桁行１０間梁間２間半規模、南北棟の切妻造本瓦葺で、門口は間口３間とし、北方に布団蔵を配し、南方は供部屋で東西棟、入母屋造とし、街道側へ１間張り出す。再建ではあるが、旧規を踏襲し本陣に相応しい表構えである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006687"},{"id":"00016558","register_sub_id":"101","register_pk":"574920","name":"田中家住宅主屋","kana":"たなかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府四條畷市大字逢阪213","lat":34.73836111,"lng":135.67366667,"geo_status":"db","era":"明治19年／昭和45年頃・同60年頃改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0966","desc":"清滝峠付近に位置する農家の主屋。石垣で造成した敷地中央に南面して建つ、入母屋造平入桟瓦葺東西棟で周囲に下屋を廻らす。東は土間、西は前後二列に３室を配し、座敷と納戸境に廊下状の部屋を設ける。大規模民家で屋敷構えとともに農村集落の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016558"},{"id":"00006690","register_sub_id":"101","register_pk":"107673","name":"田中家住宅勝手門及び納屋","kana":"たなかけじゅうたくかってもんおよびなや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51442838,"lng":135.41950315,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0444","desc":"主屋の東南、表門の西南に位置し、東西棟で建つ。切妻造桟瓦葺で、長屋門の形式をもち、東端に間口１間の門口を配し、西方は桁行５間梁間２間規模の納屋に充てる。納屋は８畳大の土間を中央に、東側に畳敷長４畳、西側に拭板敷８畳大の部屋を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006690"},{"id":"00006686","register_sub_id":"101","register_pk":"107669","name":"田中家住宅玄関及び座敷棟","kana":"たなかけじゅうたくげんかんおよびざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51471633,"lng":135.41968247,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0442","desc":"主屋の北側に接続する。桁行５間半梁間３間規模、東西棟、入母屋造本瓦葺で、接続部に東面して入母屋造妻入本瓦葺の式台玄関を置き、１０畳と８畳の２間続きの座敷を矩の手につなげる。１０畳には北面東端に押板が付き、８畳はトコと棚、付書院を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006686"},{"id":"00012587","register_sub_id":"101","register_pk":"367882","name":"田中家住宅米蔵","kana":"たなかけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治前期／昭和40年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0760","desc":"敷地南辺、長屋門と離れの間に東西棟で建つ。土蔵造平屋建、切妻造桟瓦葺、離れと同様の切石積基礎で、外壁漆喰塗の腰縦板張とし、軒は垂木形を表して塗込め、南面には与力窓を二箇所に設ける。長屋門や離れと同じく旧家の風格ある屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012587"},{"id":"00012584","register_sub_id":"101","register_pk":"367879","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積260㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0757","desc":"天野川西側の丘陵上にある地主宅。主屋は南面して建つ入母屋造本瓦葺で、正面は軒まで塗込めて虫籠窓を穿ち、袖壁を付す。西半の土間は重厚な梁組を現す。東半の床上部は三列に室を配し、東列二室を落棟とする。伝統的な民家形式を伝え、式台等に格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012584"},{"id":"00006741","register_sub_id":"101","register_pk":"107724","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51460453,"lng":135.41952939,"geo_status":"db","era":"江戸中／江戸後・江戸末増改築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中","structure":"木造平屋建、瓦葺、建築面積341㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0441","desc":"旧紀州街道に東面する屋敷地の中央に南北棟で建つ。桁行１１間半梁間７間規模、入母屋造本瓦葺のつし２階建で、南方を土間、北方を床上部とし、北西隅に座敷を配し、土間の西方に切妻造の釜屋を突き出す。改造はあるが江戸中期の形態をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006741"},{"id":"00005638","register_sub_id":"101","register_pk":"106626","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市高見の里3-167他","lat":34.573757,"lng":135.546265,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0369","desc":"屋敷地の北寄りに位置し，東西棟で建つ。桁行１０間半，梁行４間半規模，入母屋造，桟瓦葺のつし２階建で，東方を土間，西方床上部を四間取とし，２階正面に虫籠窓を開く。土間が桁行５間半分と広く，南面西方の仏間前方に勘定場を設けるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005638"},{"id":"00007647","register_sub_id":"101","register_pk":"108629","name":"田中家住宅主屋","kana":"たなかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市南新町1-50-1","lat":34.57651528,"lng":135.53689613,"geo_status":"db","era":"天保年間頃／平成19移築","year":1837,"year_source":"estimated","year_min":1830,"year_max":1844,"year_label":"天保年間頃","structure":"木造平屋建、瓦葺、建築面積247㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0527","desc":"通りの西に占める敷地の中央に北面して建つ。入母屋造で周囲に下屋庇をまわし、南側に角屋を付ける。木造つし２階建。東寄りに大戸口を開き、土間を設け、西に仏間など床上部を設ける。木柄の大きい差物で固めるなど、近世の大規模な農家建築の面影を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007647"},{"id":"00005642","register_sub_id":"101","register_pk":"106630","name":"田中家住宅外塀","kana":"たなかけじゅうたくそとべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府松原市高見の里3-167、167-1、168","lat":34.57343845,"lng":135.54619353,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、延長47m","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0373","desc":"屋敷地北辺西寄りと，西辺の土蔵より南方に建つ。切妻造，桟瓦葺の木造で，腰を竪板張，上部を白漆喰塗とする。西辺は土蔵の南に裏門を設け，南端近くに潜戸を開く。北辺は上部小壁に小判形と横長形の虫籠窓風開口部を設けて道路沿いの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005642"},{"id":"00016561","register_sub_id":"101","register_pk":"574923","name":"田中家住宅巽蔵","kana":"たなかけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府四條畷市大字逢阪213","lat":34.73836111,"lng":135.67366667,"geo_status":"db","era":"明治40年／平成15年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0969","desc":"敷地南辺東寄りに位置する米蔵。二階建切妻造平入、置屋根形式の本瓦葺で北に下屋を付す。外壁漆喰塗で軒蛇腹を廻らし、腰はモルタル洗出仕上。戸口に漆喰塗引戸を建てる。小屋組は棟木と桁に野地板を流板に張る。石垣上に建ち、旧家の屋敷構えをつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016561"},{"id":"00012588","register_sub_id":"101","register_pk":"367883","name":"田中家住宅中門","kana":"たなかけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治中期／平成10年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.4m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0761","desc":"主屋南面に張出す勘定部屋から南に延びる塀に開く一間腕木門。間口1･4メートル、切妻造本瓦葺で、疎らに割付けた垂木に強い反りを付ける。門扉は両開板戸で、軸部は赤色に塗装する。前庭と主庭を画し、旧家の庭空間を整える丁寧なつくりの庭門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012588"},{"id":"00016562","register_sub_id":"101","register_pk":"574924","name":"田中家住宅中門","kana":"たなかけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府四條畷市大字逢阪213","lat":34.73836111,"lng":135.67366667,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口1.2m、袖塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0970","desc":"主屋南側の庭入口に位置する門。一間の腕木門で屋根は桟瓦葺。土台上に立てた柱で棟木を受け、軒桁を腕木で支持し、北に袖塀を延ばす。門口に片引戸を建て、欄間は吹寄の襷桟を入れる。小規模ながら庭の景観をつくり、鯉などを飾る銅製雨樋も目を惹く中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016562"},{"id":"00006688","register_sub_id":"101","register_pk":"107671","name":"田中家住宅築地塀","kana":"たなかけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51461252,"lng":135.42001597,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長57m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0446","desc":"表門の東北隅から旧紀州街道沿いに北側の敷地境界部まで延び、折曲り延長５１ｍに及ぶ。高さは２．３ｍ、厚さは下部で６５ｃｍ、上部で５９ｃｍとし、桟瓦葺の屋根を載せる。中程には勝手口を設け、足元には街道沿い全面に亘って犬矢来を設置し景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006688"},{"id":"00012586","register_sub_id":"101","register_pk":"367881","name":"田中家住宅道具蔵","kana":"たなかけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治8年","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0759","desc":"主屋背後の敷地北辺に東西棟で建つ。土蔵造二階建、切妻造本瓦葺で、内部は東西に二分し、東妻に戸口を設けて庇を付し、西室南面にも出入口を開く。切石積基礎の外壁漆喰塗で、腰高に縦板を張り、軒に鉢巻を廻す。歴史ある集落の街路景観を形成する大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012586"},{"id":"00005640","register_sub_id":"101","register_pk":"106628","name":"田中家住宅土蔵","kana":"たなかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府松原市高見の里3-167他","lat":34.5736639,"lng":135.54619673,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積12㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0371","desc":"主屋の西南方，屋敷地西辺沿いに南北棟で建つ。桁行２間，梁間１間半規模，切妻造，本瓦葺，置屋根形式の２階建土蔵で，北面に戸口を設け，東面全面に１間幅の庇を出して物置とする。外部は漆喰塗で，西面道路沿いは腰に竪板を張る。屋敷地西面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005640"},{"id":"00012589","register_sub_id":"101","register_pk":"367884","name":"田中家住宅長屋門","kana":"たなかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治前期／平成元年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0762","desc":"敷地南面西寄りに建つ長屋門。東面切妻造、西面入母屋造の桟瓦葺で、東寄りを門口として成の高い差物を渡し、両開板戸の片側に潜戸を開く。門口の東側を物置、西側を柴小屋等とし、正面は軒まで塗込めて虫籠窓を穿つ。旧家の風格ある表構えの核をなす表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012589"},{"id":"00005639","register_sub_id":"101","register_pk":"106627","name":"田中家住宅長屋門","kana":"たなかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府松原市高見の里3-167他","lat":34.57382729,"lng":135.54637973,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0370","desc":"主屋の北東，屋敷地北辺に沿って東西棟で建つ。桁行５間半，梁間１間半規模，西を入母屋造，東を寄棟造，桟瓦葺，木造平屋建の長屋門で，西端を門口，東端を通路とし，その間に２室を設ける。門口は間口２間で東に潜戸を付ける。屋敷地北面を構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005639"},{"id":"00007648","register_sub_id":"101","register_pk":"108630","name":"田中家住宅長屋門","kana":"たなかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市南新町1-50-1","lat":34.5764859,"lng":135.53713127,"geo_status":"db","era":"文政年間／平成19移築","year":1824,"year_source":"estimated","year_min":1818,"year_max":1830,"year_label":"文政年間","structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0528","desc":"通りに東面して建つ。木造平屋建で、入母屋造本瓦葺とする。桁行１１ｍ梁間４．０ｍで、中央に４．０ｍの門口を開き、その南北に２室を配し、北室に床や天井を造る。壁は漆喰仕上げで、腰下見板張とし、出格子や与力窓を構える。重厚な外観になる長屋門の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007648"},{"id":"00012585","register_sub_id":"101","register_pk":"367880","name":"田中家住宅離れ","kana":"たなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府枚方市山之上一丁目1205","lat":34.80069,"lng":135.655151,"geo_status":"geocoded","era":"明治40年頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0758","desc":"敷地南東隅に南北棟で建つ。通りに面する南東二面は切石積基礎の漆喰塗とし、縦板を腰高に張り、周囲の建物と外観を統一する。内部は六畳の主室を中心に、庭に面した北西二面に縁を設ける。座敷飾や欄間等を端正な意匠でまとめた、落ち着いた佇まいの座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012585"},{"id":"00005641","register_sub_id":"101","register_pk":"106629","name":"田中家住宅離れ","kana":"たなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府松原市高見の里3-167他","lat":34.57364449,"lng":135.54638714,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"27 － 0372","desc":"主屋の南東に，隣地との敷地境沿いに南北棟で建つ。桁行８間，梁行２間半規模，切妻造，桟瓦葺の木造平屋建で，西面南半に縁側を配し，その東側に床付き８畳間と６畳間を並べる。北半は，落ち棟とし，納屋，風呂場，漬物小屋を納める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005641"},{"id":"00016560","register_sub_id":"101","register_pk":"574922","name":"田中家住宅離れ","kana":"たなかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府四條畷市大字逢阪213","lat":34.73836111,"lng":135.67366667,"geo_status":"db","era":"大正6年頃／昭和40年代改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0968","desc":"乾蔵の東に接続する離れ棟。平屋建切妻造桟瓦葺の東西棟で南に下屋を付し、外壁は漆喰塗仕上で腰は竪板張とする。西側は二室続きの座敷を配し、西に床と床脇、南に縁を付す。東側は一室の土間で納屋とする。乾蔵と一体となって敷地北東の景観をつくる離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016560"},{"id":"00006689","register_sub_id":"101","register_pk":"107672","name":"田中家住宅備窮倉","kana":"たなかけじゅうたくびきゅうぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉大津市助松町2-687-1他","lat":34.51472981,"lng":135.41942931,"geo_status":"db","era":"文政6","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積24㎡","structure_material":"土蔵造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0443","desc":"主屋の西方に南北棟で建つ。桁行３間梁間２間の土蔵で、屋根は切妻造桟瓦葺の置屋根とし、東面南寄りに庇を差し掛けて戸口を設け、西面に２ヶ所の小窓を開ける。飢餓対策として建設された貯穀倉で、近世村落における社会事業を物語る遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006689"},{"id":"00015489","register_sub_id":"101","register_pk":"533504","name":"中條家住宅主屋","kana":"ちゅうじょうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市旭区赤川四丁目1455他","lat":34.72983889,"lng":135.53072778,"geo_status":"db","era":"明治中期／昭和前期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"27 - 0947","desc":"日吉神社の西方に位置する農家の主屋。敷地北寄りに南面して建つ、二階建入母屋造で南・西面に下屋を付す。西に土間、東に６室を並べ、南東に床と平書院を備えた座敷を配する。正面には土間の大戸や格子窓など古風な外観を残し、農村集落の歴史を伝える民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015489"},{"id":"00007086","register_sub_id":"101","register_pk":"108068","name":"塚本家住宅蔵（旧覚兵家住宅米蔵）","kana":"つかもとけじゅうたくくら（きゅうかくひょうけじゅうたくこめぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市本町4853-5","lat":34.41580022,"lng":135.31559583,"geo_status":"db","era":"江戸末期／昭和33改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積73㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0461","desc":"敷地角地に建つ土蔵。桁行南１３ｍ北１２ｍ梁間５．８ｍの台形平面の土蔵で、屋根は切妻造本瓦葺。切込矧の石積上に建ち、外壁は養生用の下見板を張る。内部は１室で東半部に２階床を造る。廻船問屋の蔵が建ち並んでいた往時の面影を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007086"},{"id":"00010486","register_sub_id":"101","register_pk":"202522","name":"佃家煎茶室主屋","kana":"つくだけせんちゃしつしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市中央区大手通1-1","lat":34.686197,"lng":135.516799,"geo_status":"db","era":"昭和21／昭和34移築","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"27 － 0611","desc":"大阪市街地中心部に位置する煎茶室。十一畳半の「霊篁」及び七畳半の「梅渓」の茶室二室と、立礼席「蘭風」、廊下等からなる。丸太や面皮柱、竹の良材や古木などを用いた数寄屋意匠を基調とし、要所に中国風や草木形の造作を付す、趣向を凝らした煎茶室の優品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010486"},{"id":"00010487","register_sub_id":"101","register_pk":"202523","name":"佃家煎茶室土蔵","kana":"つくだけせんちゃしつどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市中央区大手通1-1","lat":34.686162,"lng":135.516733,"geo_status":"db","era":"嘉永元(1848)／昭和16・昭和20改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"27 － 0612","desc":"主屋の南西に建つ。土蔵造二階建本瓦葺の土蔵で、昭和一六年に煎茶室「独楽」に改修された。一階床は土間で磚を敷き、天井は大引天井とする。西面の壁には縦長の両開きガラス窓を二箇所設け、桟は中国風の意匠とする。大阪市街地に残る希少な近世の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010487"},{"id":"00005302","register_sub_id":"101","register_pk":"106290","name":"辻家住宅居間","kana":"つじけじゅうたくいま","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.5056468,"lng":135.5437279,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0356","desc":"東は米蔵，西は本蔵と接している。真壁造の平屋建，切妻造，桟瓦葺で，米蔵や本蔵より一段低く造る。南面は戸口を設け，北面は横長窓をつけ，腰を縦板で覆う。内部は畳敷で，居間として用いられた。本蔵，米蔵とともに敷地後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005302"},{"id":"00005301","register_sub_id":"101","register_pk":"106289","name":"辻家住宅米蔵","kana":"つじけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50563804,"lng":135.5437889,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0355","desc":"主屋の後方，敷地北辺にあり，西は居間と接する。土蔵造平屋建，東西棟の置屋根式で，南面と東面に下屋を廻し，本瓦葺とする。つくりは堅牢で，南面には引戸の開口部を設け，北面は庇付の窓と丸窓を配し，腰を縦板で覆う。整った外観意匠を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005301"},{"id":"00005305","register_sub_id":"101","register_pk":"106293","name":"辻家住宅仕切塀","kana":"つじけじゅうたくしきりべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50544938,"lng":135.54370883,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、延長13m、門付","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0359","desc":"主屋の式台玄関の西端から南に延び，西に向かう折曲り延長約１３ｍの塀。真壁造で桟瓦葺屋根を架けるが，主屋寄りには引戸を設けた門を構え，屋根を一段高く造る。主屋居室部の前庭と座敷の前庭を区切っており，屋敷の空間構成上，欠かせない要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005305"},{"id":"00005299","register_sub_id":"101","register_pk":"106287","name":"辻家住宅主屋","kana":"つじけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50554455,"lng":135.54377959,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺及び茅葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0353","desc":"いわゆる茅葺の大和棟の民家で，落棟や庇は本瓦葺とし，ほぼ南面して建つ。居室部は四間取平面で，式台玄関を備え，東側の落棟の台所はもと土間，西側に格式の高い座敷を突出する。軸部は差鴨居を用い強固な構造とする。田園風景に豪壮な佇まいを見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005299"},{"id":"00005304","register_sub_id":"101","register_pk":"106292","name":"辻家住宅高塀","kana":"つじけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50560358,"lng":135.54358675,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、延長42m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0358","desc":"長屋門の西妻から北に延び，北辺で折れて本蔵に接する。折曲り延長約４２ｍと長大で，精緻に組んだ切石積基礎上に建つ。真壁造，漆喰塗とし，腰を縦板で覆い，桟瓦の屋根を架ける。敷地西辺の境を整えるとともに，良好な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005304"},{"id":"00005303","register_sub_id":"101","register_pk":"106291","name":"辻家住宅長屋門","kana":"つじけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50538604,"lng":135.54374859,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0357","desc":"敷地南辺に建ち，東西に細長く，中央東寄りに門口を構え，この東に供部屋，西に納屋が続く。門口と供部屋が入母屋造，本瓦葺，納屋は一段高い切妻造，桟瓦葺とする。外壁は漆喰塗，腰を下見板で覆い，納屋には庇がつく。風格のある屋敷正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005303"},{"id":"00005300","register_sub_id":"101","register_pk":"106288","name":"辻家住宅本蔵","kana":"つじけじゅうたくほんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪狭山市池之原4-927","lat":34.50564904,"lng":135.54366862,"geo_status":"db","era":"明治3","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0354","desc":"土蔵造２階建，南北棟の本瓦葺屋根とし，外壁は漆喰塗で軒裏まで塗り込め，ほぼ１階の階高まで縦板で覆う。１階南妻面の戸口は廊下で主屋と連続し，妻面の１，２階には庇付の窓を設ける。全体につくりは丁寧。主屋後方にあり，敷地北辺の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005300"},{"id":"00007646","register_sub_id":"101","register_pk":"108628","name":"辻野家住宅主屋","kana":"つじのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市向野町123-1他","lat":34.45808536,"lng":135.57690636,"geo_status":"db","era":"江戸後期／江戸後期増築・昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0526","desc":"街道沿いの敷地の中央に南面して建つ。木造平屋建、茅葺（鉄板仮葺）の高塀造で、南面東寄りに入母屋造本瓦葺の玄関棟を突き出し、東面に角座敷を付ける。玄関棟は式台と使者の間からなり、角座敷にはトコや付書院を構える。地方における上層農家の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007646"},{"id":"00010675","register_sub_id":"101","register_pk":"201249","name":"辻本家住宅主屋","kana":"つじもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大東市御領3-484","lat":34.718605,"lng":135.614289,"geo_status":"db","era":"江戸末期／平成24年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鋼板葺一部瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0630","desc":"集落内の敷地中央に北面して建つ民家。寄棟造、茅葺型鋼板葺で、桟瓦葺の下屋を廻らせる。内部は東寄りを広い土間とする。床上部の前列は東から板の間、六畳、床を備えた八畳とし、六畳前面に式台を構える。庄屋を務めた旧家の格式を伝える民家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010675"},{"id":"00013279","register_sub_id":"101","register_pk":"366268","name":"筒井家住宅主屋","kana":"つついけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55583611,"lng":135.50073889,"geo_status":"db","era":"江戸前期／江戸後期・同末期増築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、茅葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0793","desc":"御廟表塚古墳近傍にある新田開発者の住宅。主屋は新田管理所を改修し、住居としたもの。敷地ほぼ中央に南面して建つ入母屋造茅葺で、四周に下屋を廻す。西に広い土間、東に２列６室を並べ、北面中央と北東に角屋が突出する。新田開発の歴史を示す貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013279"},{"id":"00013280","register_sub_id":"101","register_pk":"366269","name":"筒井家住宅座敷棟","kana":"つついけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55577222,"lng":135.50085556,"geo_status":"db","era":"江戸中期／江戸後期増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0794","desc":"主屋南東に接続し、西面して建つ。Ｌ字形の離れの居住棟を改修して主屋と接続し、座敷とした。切妻造本瓦葺で、西に式台玄関と突出した角屋を設け、三方に縁を廻す。内部は二列四室で南西に土間を設け、北東と南東室に床を設ける。数寄屋風の上質な座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013280"},{"id":"00013281","register_sub_id":"101","register_pk":"366270","name":"筒井家住宅茶室","kana":"つついけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55586667,"lng":135.50086667,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0795","desc":"座敷棟の北東に接続して建つ。北面入母屋造、南面切妻造の桟瓦葺で、南面に銅板葺の落棟を付す。内部は北を三畳台目茶室、南を水屋とし、茶室西面南側を手前座、対角の東面北側を床とし、貴人口のみを開く。不整形な平面が変化に富む外観をつくる上質な茶席。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013281"},{"id":"00013283","register_sub_id":"101","register_pk":"366272","name":"筒井家住宅土蔵","kana":"つついけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55598333,"lng":135.50076667,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積28㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0797","desc":"主屋北側角屋に接続して建つ家財蔵。木造2階建、土蔵造本瓦葺で、南面東側に戸口を開く。外壁は漆喰塗で鉢巻四段を廻し、腰を縦板張とする。内部は板敷で壁を竪板張とし、登梁形式の小屋組に棟から桁まで野地板を流板に張る。敷地北辺の屋敷構を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013283"},{"id":"00013284","register_sub_id":"101","register_pk":"366273","name":"筒井家住宅土塀","kana":"つついけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55558056,"lng":135.50050833,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土塀、瓦葺、総延長134m","structure_material":"土塀","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0798","desc":"東側庭園を囲う土塀。門長屋南辺西方より東に延びて南に折曲り、さらに東に延びて北折し土蔵北東に至る。東面中程に潜戸を開く。本瓦葺で、団子積、荒壁仕上の壁芯に、柱を立てて腕木を出し、出桁を渡して軒を支える。屋敷構成立時の敷地景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013284"},{"id":"00013282","register_sub_id":"101","register_pk":"366271","name":"筒井家住宅門長屋","kana":"つついけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市北区中百舌鳥町四丁535","lat":34.55586944,"lng":135.50058056,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0796","desc":"敷地南西の敷地に沿って建つ。入母屋造本瓦葺で、南北棟の中央やや北寄りに一間の門と半間の脇戸を開き、北端は西、南端は東に矩折れた平面を成す。外壁は漆喰塗で、敷地外側は大壁造で軒裏まで塗込め、内側は真壁造とする。屋敷構成立の変遷を物語る建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013282"},{"id":"00008737","register_sub_id":"101","register_pk":"149458","name":"寺田家住宅石垣塀","kana":"てらだけじゅうたくいしがきへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町213他","lat":34.44487171,"lng":135.35345576,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造、総延長56m","structure_material":"石造","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0548","desc":"敷地の西辺、表門の南北に矩折れに延びる石垣塀で、総延長56ｍ、最高高さ3.4ｍを測り、北寄りに半円アーチの通用門を開く。躯体は瘤出し仕上げの花崗岩を布積とし、頂部に見切り石を伏せる。重厚な趣の街路景観を形成する石垣塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008737"},{"id":"00008733","register_sub_id":"101","register_pk":"149454","name":"寺田家住宅内蔵","kana":"てらだけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町213他","lat":34.44491491,"lng":135.35378769,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0544","desc":"主屋東面に渡り廊下を介して接続する内蔵で、桁行4.9ｍ梁間3.9ｍ、土蔵造2階建、切妻造本瓦葺である。布石積基礎に建ち、1階東面と2階の南・北面に小窓を穿つ。スパニッシュ様式を採り入れた主屋と対照的な外観で、敷地景観に変化を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008733"},{"id":"00004790","register_sub_id":"101","register_pk":"105780","name":"寺田家住宅内蔵","kana":"てらだけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.58953428,"lng":135.62041493,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0323","desc":"主屋後方にあり，蔵前が主屋と連続している。南北棟の切妻造，土蔵造２階建で，外壁は腰を「柏原舟」の舟板を用いた縦板張とし，中間を石張風につくり，上部は漆喰塗で鉢巻を廻す。屋根は置屋根式瓦葺で，桁・垂木まで漆喰塗とするなど，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004790"},{"id":"00008731","register_sub_id":"101","register_pk":"149452","name":"寺田家住宅主屋","kana":"てらだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町213他","lat":34.44491269,"lng":135.35363032,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積213㎡","structure_material":"木造2階一部平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0542","desc":"敷地北寄りに建ち、建築面積213㎡、2階1部平屋建で、屋根は寄棟造や入母屋造などで構成する。玄関まわりや応接室、屋根に、スパニッシュ様式を採用する一方で、座敷などは数寄屋風を加味した和風意匠とする。和洋意匠を破綻なく複合させた近代住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008731"},{"id":"00004792","register_sub_id":"101","register_pk":"105782","name":"寺田家住宅米蔵","kana":"てらだけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.58946842,"lng":135.620605,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造平屋建、瓦葺、建築面積85㎡","structure_material":"土蔵造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0325","desc":"敷地のほぼ中央，北面して建つ。南北棟の切妻造，妻入，瓦葺の土蔵造中２階建で，東に切妻造，平屋建の納屋を附属し，北面に一連の吹放しの下屋庇を架ける。下部は縦板で覆い，上部は軒裏まで漆喰塗とする。屋敷構成に欠かせない要素で，つくりも丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004792"},{"id":"00004788","register_sub_id":"101","register_pk":"105778","name":"寺田家住宅主屋","kana":"てらだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.58947866,"lng":135.6203191,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0321","desc":"旧奈良街道に西面して建つ。切妻造，本瓦葺，平入，正面下屋庇付のつし２階建町家で，北半は居室部，南半は土間部として，北妻は段違いで座敷を延ばす。正面の上部は壁から軒裏まで漆喰塗とし，虫籠窓や１階の多彩な格子など，風格のある佇まいを呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004788"},{"id":"00008732","register_sub_id":"101","register_pk":"149453","name":"寺田家住宅新宅","kana":"てらだけじゅうたくしんたく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町113-3","lat":34.44468612,"lng":135.35387084,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"converted","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積139㎡","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0543","desc":"主屋と中庭を挟んで建ち、建築面積139㎡、鉄筋コンクリート造平屋1部2階建で、屋根は陸屋根及び切妻造桟瓦葺とする。東半の客室部に玄関を構え、西半の居室部は南庭に面してテラスを設ける。和風意匠を巧みに採り入れた鉄筋コンクリート造住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008732"},{"id":"00008734","register_sub_id":"101","register_pk":"149455","name":"寺田家住宅外蔵","kana":"てらだけじゅうたくそとぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町213他","lat":34.44486411,"lng":135.35384753,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0545","desc":"内蔵の東側に、主屋に向いて建つ。桁行6.0ｍ梁間4.0ｍ、土蔵造2階建、切妻造本瓦葺で、西面を出入口として庇を付ける。洗出しモルタル仕上げの基礎に建ち、腰は竪板を高く張り、軒蛇腹は漆喰で塗り込める。伝統的な土蔵造になる蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008734"},{"id":"00004791","register_sub_id":"101","register_pk":"105781","name":"寺田家住宅土蔵","kana":"てらだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.58960152,"lng":135.62064862,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0324","desc":"敷地のほぼ中央にある。東西棟の切妻造，瓦葺，土蔵造２階建で，南面に戸口を設ける。基礎は花崗岩布積，外壁は腰を縦板張とし，上部は桁・垂木まで漆喰塗とする。２階妻面には鉄格子入，小庇付の窓を設ける。堅牢なつくりで，屋敷構成に欠かせない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004791"},{"id":"00008735","register_sub_id":"101","register_pk":"149456","name":"寺田家住宅納屋","kana":"てらだけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町506","lat":34.44501313,"lng":135.35360047,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋地下1階建、瓦葺、建築面積20㎡","structure_material":"木造平屋地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0546","desc":"主屋背面の勝手口北側に建ち、桁行6.0ｍ梁間3.0ｍ、木造平屋地下1階建、寄棟造桟瓦葺で、南面を出入口として庇を付ける。1階西半と地階を納屋とし、1階東半は男衆部屋として押入を備える。旧家における使用人の生活を伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008735"},{"id":"00004789","register_sub_id":"101","register_pk":"105779","name":"寺田家住宅離れ","kana":"てらだけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.5895809,"lng":135.62087928,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積171㎡","structure_material":"木造平屋一部2階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0322","desc":"東西に細長い敷地東側にある。北側は切妻造，本瓦葺の平屋建で，南側はＴ字型の中２階建になり，入母屋造，桟瓦葺とする。東・西面のほぼ中央に式台玄関を設ける。内部は瀟洒な書院造風に纏められており，巧緻な板欄間など，要所に凝ったつくりがみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004789"},{"id":"00004794","register_sub_id":"101","register_pk":"105784","name":"寺田家住宅東門","kana":"てらだけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.589653,"lng":135.621063,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0327","desc":"東西に長い敷地の東辺中央にある。小規模な薬医門であるが，親柱上に絵様付肘木をのせ，冠木と梁を受ける。軒は一軒疎垂木，屋根は切妻造，本瓦葺で，冠木も瓦棒板葺屋根で覆う。離れ東面の式台玄関に応じた位置にあり，屋敷後方の景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004794"},{"id":"00008736","register_sub_id":"101","register_pk":"149457","name":"寺田家住宅本門","kana":"てらだけじゅうたくほんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市新町213他","lat":34.44470921,"lng":135.35345146,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"converted","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、間口3.7m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"27 － 0547","desc":"敷地西辺南端の石段上に建つ表門で、茅葺風の急勾配屋根が特徴的である。木造、1間薬医門、切妻造桟瓦葺で、軒先を銅板葺とし、軸部材や垂木には杉の絞り丸太を用いる。控壁に丸窓を穿ち、門口や潜りの桟唐戸に格狭間を透かすなど、瀟洒な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008736"},{"id":"00004793","register_sub_id":"101","register_pk":"105783","name":"寺田家住宅南門","kana":"てらだけじゅうたくみなみもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府柏原市今町2-1-14","lat":34.58941524,"lng":135.62050759,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0326","desc":"敷地南辺の中央西寄りに構える。真壁造で，中央に門口を設け，内開き戸をつけ，西側は一室の納屋として，内側に引違戸をつける。屋根は切妻造，本瓦葺とし，一軒疎垂木の化粧屋根裏で，梁組と束立の小屋組をみせる。米蔵とともに屋敷南辺の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004793"},{"id":"00003682","register_sub_id":"101","register_pk":"104672","name":"寺西家阿倍野長屋","kana":"てらにしけあべのながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町1-50-52","lat":34.63314,"lng":135.51630847,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積201㎡","structure_material":"木造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"27 － 0268","desc":"大正～昭和期開発の住宅地に建つ。構造上は左右２軒ずつに分割され，間に防火壁を立ち上げている。各戸毎に妻入の玄関部を設け，背面側に坪庭を配する。２階を接客用空間とする点や，当初から各戸に風呂を設ける点が特色で，戦前の長屋建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003682"},{"id":"00005192","register_sub_id":"101","register_pk":"106182","name":"寺西家住宅蔵","kana":"てらにしけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町1-50-25","lat":34.63322569,"lng":135.51604342,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"27 － 0339","desc":"主屋西側，敷地北西隅にある。たちの高い土蔵造２階建で，屋根は南北棟の切妻造，本瓦葺である。基礎は花崗岩の石積，外壁は漆喰塗で頂部に鉢巻を廻す。南妻に庇付の扉口と窓，北妻には窓をそれぞれ設ける。北妻が街路に面し，主屋とともに景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005192"},{"id":"00005191","register_sub_id":"101","register_pk":"106181","name":"寺西家住宅主屋","kana":"てらにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町1-50-25","lat":34.633156,"lng":135.516113,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積102㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"27 － 0338","desc":"東が平屋，西が２階建で，入母屋造屋根を巧みに架ける。１階は南東部が玄関，平面は中廊下式で，２階奥を床・棚付の座敷とする。１階玄関横の応接室は切妻造で，内外とも洋風意匠になる。街区北東の角地にあり，変化に富んだ外観は地域景観上，際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005191"},{"id":"00004784","register_sub_id":"101","register_pk":"105774","name":"天理教北阪分教会教職舎","kana":"てんりきょうきたさかぶんきょうかいきょうしょくしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府柏原市片山町1-19","lat":34.56868,"lng":135.632599,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造3階建、瓦葺、建築面積306㎡、塔屋付","structure_material":"木造3階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0317","desc":"もと個人住宅。２階建に望楼を載せた木造３階建で，八角形の塔屋をあげ，屋根は緑釉瓦葺とし，千鳥破風やコーニスなど和洋折衷の変化に富んだ外観を構成する。壁体は，「モーラ式構成網」という特殊な金網を用いたコンクリート造で，類例をみない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004784"},{"id":"00004786","register_sub_id":"101","register_pk":"105776","name":"天理教北阪分教会倉庫","kana":"てんりきょうきたさかぶんきょうかいそうこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府柏原市片山町1-19","lat":34.56870293,"lng":135.6323209,"geo_status":"db","era":"昭和14頃／昭和20代増築","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積104㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0319","desc":"教職舎の西側にある。東西棟の切妻造，緑釉瓦葺の２階建倉庫。当初はヴォールト天井の主体部の南に下屋を設けた形式の平屋建で，妻壁に痕跡が残る。１階出入口両脇の柱にはコリント式柱頭飾をつける。壁体は「モーラ式構成網」を用いたコンクリート造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004786"},{"id":"00004785","register_sub_id":"101","register_pk":"105775","name":"天理教北阪分教会離れ","kana":"てんりきょうきたさかぶんきょうかいはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府柏原市片山町1-19","lat":34.56831083,"lng":135.632568,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0318","desc":"木造２階建の住宅で，屋根は棟違いの寄棟造，桟瓦葺，外周の階境や２階の横長窓には板軒風の庇を廻し，２階窓下には洋風高欄風飾りを施す。外観は土蔵造に見えるが，壁体は，教職舎と同じく「モーラ式構成網」という特殊な金網を用いたコンクリート造である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004785"},{"id":"00004787","register_sub_id":"101","register_pk":"105777","name":"天理教北阪分教会欄干","kana":"てんりきょうきたさかぶんきょうかいらんかん","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府柏原市片山町1-19","lat":34.5681025,"lng":135.63275457,"geo_status":"db","era":"昭和14頃","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"コンクリート造、延長13m","structure_material":"コンクリート造","registered":"2005.07.12(平成17.07.12)","register_no":"27 － 0320","desc":"敷地南側のアプローチ沿いにある。延長１３ｍ，高さ５７ｃｍの規模で，土台上に建てた円柱で手摺を受ける。教職舎などと同じ類例の見られない工法による工作物で，「モーラ式構成網」という特殊な金網を用いたコンクリート造で，円柱間に金網を露出させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004787"},{"id":"00007643","register_sub_id":"101","register_pk":"108625","name":"土肥家住宅主屋","kana":"どいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区九条3-21-29","lat":34.6779745,"lng":135.46916179,"geo_status":"db","era":"昭和11／昭和34改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積121㎡","structure_material":"木造2階建","registered":"2009.04.28(平成21.04.28)","register_no":"27 － 0523","desc":"安治川の南岸地域の市街地に建つ平入町家。北面する木造２階建で、切妻造桟瓦葺。東端に通用口、中央に本玄関、西に出格子窓を構え、２階は大壁とし、出桁造の軒まで塗り込め、両端にウダツをつくる。内部は土間上部に豪快な梁組を見せる。近代町家の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007643"},{"id":"00001119","register_sub_id":"101","register_pk":"102109","name":"桃林堂板倉家住宅","kana":"とうりんどういたくらけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府八尾市東本町2-5-12","lat":34.62822053,"lng":135.60382216,"geo_status":"db","era":"18世紀前期","year":1750,"year_source":"estimated","year_min":1701,"year_max":1750,"year_label":"18世紀前期","structure":"木造平屋建，茅葺一部瓦葺，建築面積158㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"27 － 0060","desc":"代々河内木綿の問屋を営んだ旧家で、大正期に現家屋敷に移住したという。間口９間半、奥行４間の大型の民家。平面は右手５間分が土間で、居室部は整形４間取元であったものを土間境の広縁を居室に改造している。切妻茅葺屋根の高塀造になる民家の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001119"},{"id":"00015202","register_sub_id":"101","register_pk":"530626","name":"戸田家住宅（旧服部家住宅）主屋","kana":"とだけじゅうたく（きゅうはっとりけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東住吉区北田辺六丁目16他","lat":34.62959167,"lng":135.527575,"geo_status":"db","era":"昭和13年／昭和40年代改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"27 - 0935","desc":"近鉄北田辺駅南西に位置し、旧材木商が建てた大塀造の住宅主屋。敷地奥に南面して建つ２階建入母屋造桟瓦葺で一階は玄関から北へ通す中廊下の東西に和室を並べ、南西の庭に面して主座敷を配す。床柱にスギの絞丸太など良材を用い、材木商らしい上質なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015202"},{"id":"00011355","register_sub_id":"101","register_pk":"209192","name":"中井家住宅表門長屋","kana":"なかいけじゅうたくおもてもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府箕面市桜四丁目430-1他","lat":34.822987,"lng":135.462966,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0653","desc":"敷地南面に構える、東面切妻造、西面入母屋造、本瓦葺の長屋門。主屋の式台の正面に門口を設け、木太い軸部にケヤキ板の扉を開く。門口の東西には使用人部屋などを配し、南面は腰を簓子下見板張として出格子窓と与力窓を設ける。旧家の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011355"},{"id":"00013285","register_sub_id":"101","register_pk":"366274","name":"永井家住宅主屋","kana":"ながいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府吹田市長野東2131","lat":34.79293889,"lng":135.54494722,"geo_status":"db","era":"大正12年頃／昭和50年頃改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0799","desc":"千里丘陵地南端に建つ藤井厚二設計の住宅。二階建で雁行に部屋を配した不整形な平面を有し、南側の畳間は板間より一段高くし、中央の矩折階段上の窓から光を落とす。板間は床や網代天井など和風要素を組み合わせる。聴竹居以前に遡る希少な藤井の作品の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013285"},{"id":"00011354","register_sub_id":"101","register_pk":"209191","name":"中井家住宅主屋","kana":"なかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府箕面市桜四丁目430-1他","lat":34.823172,"lng":135.462939,"geo_status":"db","era":"天保7／嘉永6頃改修","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"木造2階建、瓦葺、建築面積266㎡、塀付","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0652","desc":"敷地中央に南面する入母屋造桟瓦葺で、南・東面の下屋を本瓦葺とする。西半の床上部は六間取を基本として表列に座敷を並べ、表列中央に式台を設け、脇の勘定場に格子をたてる。土間の軸組は木太く重厚で座敷飾も洗練され、江戸末期の上層農家の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011354"},{"id":"00011358","register_sub_id":"101","register_pk":"209195","name":"中井家住宅高塀","kana":"なかいけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府箕面市桜四丁目430-1他","lat":34.82292502,"lng":135.46284216,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、延長18m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"27－0656","desc":"表門長屋の南西隅から矩折れにのびて敷地南西隅を画す塀。布石基礎に柱を立て、腕木で軒を受ける形式で、切妻造桟瓦葺とする。腰を竪板張として上部を鼠漆喰塗で仕上げ、南面の二ヶ所に格子を入れる。表門長屋と一連の外観で地域の景観形成に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011358"},{"id":"00013286","register_sub_id":"101","register_pk":"366275","name":"永井家住宅土蔵","kana":"ながいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府吹田市長野東2131","lat":34.79301389,"lng":135.54488333,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"27 － 0800","desc":"主屋の北に建つ。土蔵造二階建で、屋根は切妻造銅板葺の置屋根で、小屋組はトラスとする。外壁は漆喰塗で鉢巻を廻し、腰を海鼠壁とする。正方形平面で正面に軒の出の大きな庇を付し、基礎は鉄筋コンクリート造の床板を四隅で支えるなど、独特の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013286"},{"id":"00011356","register_sub_id":"101","register_pk":"209193","name":"中井家住宅西蔵","kana":"なかいけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府箕面市桜四丁目430-1他","lat":34.823262,"lng":135.462789,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0654","desc":"主屋裏の北西側に南北棟で建つ。土蔵造二階建、桁行四・九メートル梁間三・九メートル、置屋根式の切妻造本瓦葺で東面南寄りを戸口とし、吹放の下屋を設ける。外壁漆喰塗で鉢巻を廻らし、二階南妻の小窓に持送付の庇を付す。主屋背面の庭空間に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011356"},{"id":"00011357","register_sub_id":"101","register_pk":"209194","name":"中井家住宅庭門及び塀","kana":"なかいけじゅうたくにわもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府箕面市桜四丁目430-1他","lat":34.82305178,"lng":135.46292597,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"庭門 木造、瓦葺、間口1.2m 塀 木造、瓦葺、総延長12m","structure_material":"庭門 木造","registered":"2016.11.29(平成28.11.29)","register_no":"27－0655","desc":"主屋式台の西側柱から南にのびる門と塀。庭門は間口一・二メートルの腕木門、切妻造桟瓦葺で舞良戸両開とする。塀は腰を竪板張、壁を中塗仕上として欄間に格子を入れ、庭門の柱際に波紋の繰形を施す障泥板を飾る。前庭と主庭を画し、屋敷構えを引立てる門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011357"},{"id":"00007085","register_sub_id":"101","register_pk":"108067","name":"名加家住宅隠居屋","kana":"なかけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市南町1414他","lat":34.44734112,"lng":135.35302543,"geo_status":"db","era":"明治5頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0460","desc":"主屋の東隣に増築され、北面して建つ。建築面積５３㎡、木造つし２階建、切妻造本瓦葺。東寄りに続き座敷を配し、正面に出格子を造る。軒高や仕様を主屋と調和した外観とするが、虫籠窓は矩形として変化を与える。主屋とともに町並み景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007085"},{"id":"00007084","register_sub_id":"101","register_pk":"108066","name":"名加家住宅主屋","kana":"なかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市南町1414他","lat":34.44739971,"lng":135.35290795,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0459","desc":"通りに北面して、隠居屋と並び建つ。建築面積１１３㎡、木造つし２階建、切妻造本瓦葺。１階の西半は、３室を２列に配し、正面に出格子をつくる。２階は軒裏まで漆喰で塗り込め、木瓜形の虫籠窓を並べる。重厚な外観で、貝塚寺内町の町並み景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007084"},{"id":"00016548","register_sub_id":"101","register_pk":"574910","name":"中谷家住宅戌亥大蔵","kana":"なかたにけじゅうたくいぬいおおくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市東成区大今里二丁目174","lat":34.67314778,"lng":135.54834278,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0956","desc":"敷地の北西隅に位置する家財蔵。南面して切石積基礎に建つ二階建切妻造妻入本瓦葺で、外壁は漆喰塗、腰は竪板張とする。各階一室の板敷で、小屋組は太い地棟の和小屋。棟木と桁に野地板を流板に張る。戸口に鉄製両開戸を建てた重厚なつくりで桁行長大な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016548"},{"id":"00016546","register_sub_id":"101","register_pk":"574908","name":"中谷家住宅主屋","kana":"なかたにけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市東成区大今里二丁目174","lat":34.67314778,"lng":135.54834278,"geo_status":"db","era":"大正15年／昭和33年増築、同52年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺及び銅板葺、建築面積258㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0954","desc":"熊野大神宮北方の住宅地に位置する和風住宅の主屋。敷地中央に南面して建つ２階建片入母屋造平入で、東に洋館、西に隠居棟及び便所棟を接続する。１２畳の主座敷は、床柱に瘤付丸太、床脇や縁板にケヤキの一枚板を用いるなど材料吟味した上質な近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016546"},{"id":"00016549","register_sub_id":"101","register_pk":"574911","name":"中谷家住宅辰巳蔵","kana":"なかたにけじゅうたくたつみくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区大今里二丁目174","lat":34.67314778,"lng":135.54834278,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0957","desc":"主屋南東に位置する家財蔵。西面して建つ二階建切妻造平入本瓦葺で、戸口に桟瓦葺軒先銅板葺庇を付す。外壁は漆喰塗で腰に定規筋を通し水切を付す。内部は各階１室の板敷で、小屋組は束立の和小屋。主屋へ至る通路脇に建ち、金庫風の鉄製扉が重厚な姿の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016549"},{"id":"00016547","register_sub_id":"101","register_pk":"574909","name":"中谷家住宅茶室","kana":"なかたにけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区大今里二丁目174","lat":34.67314778,"lng":135.54834278,"geo_status":"db","era":"昭和3年／昭和9年・同25年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0955","desc":"主屋南西に渡廊下で接続する茶室。平屋建片入母屋造桟瓦葺、軒先銅板葺で、北に入母屋造の落棟を付す。内部は４畳半茶室と三畳の水屋からなり、茶室は西に床と床脇を構え、葭簀張天井とする。床柱に捻れのある変木を用い、円弧状の狆潜など自由な意匠の茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016547"},{"id":"00016550","register_sub_id":"101","register_pk":"574912","name":"中谷家住宅門及び塀","kana":"なかたにけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市東成区大今里二丁目174","lat":34.67314778,"lng":135.54834278,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"門 木造、瓦葺及び銅板葺、間口2.0m 塀 木造、瓦葺、総延長30m","structure_material":"門 木造","registered":"2026.02.10(令和8.02.10)","register_no":"27 - 0958","desc":"敷地南面に建つ高塀と東寄りに開けた門。門は通りより引き込み、門口に瓦葺軒先銅板葺の腕木庇を付し、引違の格子戸を建てる。塀は屋根を桟瓦葺とし、外壁真壁で漆喰塗仕上、腰は高く竪板を張る。瀟洒なつくりの門及び塀で、通りに面し歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016550"},{"id":"00003447","register_sub_id":"101","register_pk":"104437","name":"中西家住宅内蔵","kana":"なかにしけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.78035386,"lng":135.53815573,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0240","desc":"長屋門勝手口の北側に接続する切妻造，本瓦葺の２階建土蔵。４間に２間半の規模で，西面北寄りに入口を設ける。小屋は桁行き中央に起った梁を架け渡し，束立てで太い棟木と母屋を受ける。キザラ小屋，長屋門とともに屋敷正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003447"},{"id":"00003446","register_sub_id":"101","register_pk":"104436","name":"中西家住宅勘定部屋","kana":"なかにしけじゅうたくかんじょうべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.7804331,"lng":135.53812552,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0239","desc":"敷地中央北寄りにある主屋の下手東側にある。南北棟の入母屋造，桟瓦葺で，８畳２間の続座敷と４畳の納戸（当初は竈のある土間）からなる。天保６年の屋敷絵図には描かれておらず，建築年代は明治期に下ると見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003446"},{"id":"00003450","register_sub_id":"101","register_pk":"104440","name":"中西家住宅キザラ小屋（納屋）","kana":"なかにしけじゅうたくきざらごや（なや）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.78006476,"lng":135.53800993,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0243","desc":"敷地南面の長屋門西側に土塀を兼ねて東西に細長く建つ桟瓦葺の小屋。敷地内側になる北面は吹き放しで，農作業等で使う丸太等の長尺部材を収納するため，長屋門前庭に面する東妻に両開きの扉口を構える。長屋門，内蔵とともに屋敷正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003450"},{"id":"00003444","register_sub_id":"101","register_pk":"104434","name":"中西家住宅主屋","kana":"なかにしけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市岸部中４丁目８２３－１ 他","lat":34.78040383,"lng":135.53787459,"geo_status":"db","era":"文政9","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積436㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0237","desc":"中西家は島下郡１４か村の大庄屋を勤めた家柄。主屋は１０間半に５間のつし２階の主体部とその上手妻に接続する座敷棟，上手前方の玄関棟からなる大規模なもの。建築年代が明らかで襖など内装も良く残る。摂津地方における江戸後期の上層農家主屋の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003444"},{"id":"00003448","register_sub_id":"101","register_pk":"104438","name":"中西家住宅土蔵一","kana":"なかにしけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.78044666,"lng":135.53762014,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0241","desc":"主屋の背面北側に位置する２棟の土蔵のうち西側の２階建土蔵。天保の屋敷図では主屋に接続しているが，明治期に北側へ曳家し西側に増築している。現在は主屋との間に住居を新築し，これと一体として座敷に使っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003448"},{"id":"00003449","register_sub_id":"101","register_pk":"104439","name":"中西家住宅土蔵二","kana":"なかにしけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.78051628,"lng":135.53771352,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0242","desc":"主屋の背面北側に位置する２棟の土蔵のうち東側の２階建土蔵。土蔵一同様屋敷図では主屋に接続しているが，明治期に北側に曳き家している。内部は東西２室に仕切られ，西側の部屋は２階床を撤去して住居の納戸に活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003449"},{"id":"00003445","register_sub_id":"101","register_pk":"104435","name":"中西家住宅長屋門","kana":"なかにしけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府吹田市岸部中四丁目８２３－１ 他","lat":34.78018745,"lng":135.5381351,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"27 － 0238","desc":"旧吉志部郷東村の西北に広大な敷地を占める中西家敷地の南正面中央にある１０間に２間半の長大な門。通り沿いに３ｍほどの空堀状前庭を設け，門前を広く取る点に特色がある。東妻を北側に折り曲げて内蔵に接続し，この部分に普段の通用門である勝手口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003445"},{"id":"00004005","register_sub_id":"101","register_pk":"104995","name":"中山家住宅北二階蔵","kana":"なかやまけじゅうたくきたにかいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58911981,"lng":135.564682,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0281","desc":"主屋台所の北に接続する。桁行５間半梁間２間で，１階南端１間半は内蔵として台所に蔵前を開く。西面中央の戸口と台所の間には濡れ縁と瓦葺庇がつく。外壁は白漆喰塗で，腰と北妻が縦羽目板張。小屋組は地棟に登り梁を架け，切妻造，本瓦葺の置屋根を載せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004005"},{"id":"00004006","register_sub_id":"101","register_pk":"104996","name":"中山家住宅米蔵","kana":"なかやまけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.589184,"lng":135.564682,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0282","desc":"北二階蔵の北に建つ。桁行２間半梁間２間の土蔵造平屋建で，外壁は中塗仕上げとする。東面南端の戸口に鉄板葺の小庇をつけ，西面北端に窓を開く。土台を束立とし，床下に通風をとる。小屋組は梁に束立てで棟木と母屋を受ける。屋根は切妻造の置屋根。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004006"},{"id":"00003998","register_sub_id":"101","register_pk":"104988","name":"中山家住宅主屋","kana":"なかやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58900799,"lng":135.56468172,"geo_status":"db","era":"文化2／天保元増築","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積439㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0274","desc":"木造つし２階建，整形六間取の農家で，桁行１１間半の東４間を土間とする。屋根は瓦葺で土間上部に越屋根を載せる。西側落棟の奥座敷３室は後の増築。南正面に玄関，北に内蔵，東に井戸のある土間を接続する。材太く，造作も上質で，豪農の威風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003998"},{"id":"00004007","register_sub_id":"101","register_pk":"104997","name":"中山家住宅瀬戸物蔵","kana":"なかやまけじゅうたくせとものぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58925374,"lng":135.564682,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0283","desc":"米蔵の北に建つ，桁行３間梁間２間の土蔵造平屋建，切妻造，桟瓦葺。東面南寄りの戸口に瓦葺庇をつけ，西面中央に鉄扉付の窓を開く。外壁は漆喰塗で，下半は縦羽目板張とする。内部は板敷，四周に棚を設け，陶磁器類を納める。小屋組は地棟に登り梁を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004007"},{"id":"00004010","register_sub_id":"101","register_pk":"105000","name":"中山家住宅長屋","kana":"なかやまけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58937573,"lng":135.56448482,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0286","desc":"敷地北辺に建つ桁行１８間梁間１間半の物置。東端入母屋造，西端切妻造の屋根を桟瓦葺とする。外壁は東面が黒漆喰塗，北面が土壁で，腰は縦羽目板張。西面は板張とする。東７間が木小屋で，以下２間毎に仕切り，西端３間は水車置場。北からの景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004010"},{"id":"00004009","register_sub_id":"101","register_pk":"104999","name":"中山家住宅長屋門","kana":"なかやまけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58877354,"lng":135.564865,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0285","desc":"敷地正面を飾る長屋門。敷地南東角に南面する。桁行４間半梁間２間の入母屋造，本瓦葺。両開門扉の右手に脇戸がつく。東側桁行１間半は供部屋で，北へ２間延びて寮に達する。西側１間は納屋で南へ半間広げる。北面屋根は西に続く二階蔵の蔵前まで一連とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004009"},{"id":"00004003","register_sub_id":"101","register_pk":"104993","name":"中山家住宅南蛮蔵","kana":"なかやまけじゅうたくなんばんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58890591,"lng":135.56485,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0280","desc":"敷地東辺，主屋東端に接続し，南に寮が続く。砂糖等の渡来品を納めた。土蔵造平屋建，切妻造，本瓦葺で，西面戸口に本瓦葺の庇がつく。外壁は漆喰塗で，腰を縦羽目板張とする。桁行２間半梁間２間で，曲材の梁２本に立てた束を貫で固め，母屋と地棟を受ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004003"},{"id":"00004002","register_sub_id":"101","register_pk":"104992","name":"中山家住宅二階蔵","kana":"なかやまけじゅうたくにかいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.5887789,"lng":135.56473036,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0278","desc":"敷地の南端，長屋門の西に接続する道具蔵。桁行３間梁間２間の土蔵造で，北面に長屋門から一続きの庇をつけ蔵前とする。外壁は白漆喰塗で，腰は縦羽目板張。南面の２階に２箇所の窓を開く。小屋組は地棟に登り梁を架け，切妻造，本瓦葺の置屋根を載せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004002"},{"id":"00004000","register_sub_id":"101","register_pk":"104990","name":"中山家住宅寝部屋","kana":"なかやまけじゅうたくねべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58914653,"lng":135.56473591,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積8㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0276","desc":"主屋の北方，北二階蔵の東に接続する使用人の休憩所。北二階蔵の外壁から片流の瓦葺屋根をかける。外壁は漆喰塗，東面南半に板戸を建て，両妻と平側にガラス障子の高窓を開く。正面に腕木で支えた切妻屋根は，かつて併行していた土蔵との間に設けられたもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004000"},{"id":"00004011","register_sub_id":"101","register_pk":"105001","name":"中山家住宅塀","kana":"なかやまけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58940534,"lng":135.56427361,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、延長57m","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0287","desc":"敷地外周の石積水路沿いに建つ瓦葺塀。外側は主屋東端から本蔵まで２２ｍが縦羽目板張と黒漆喰塗，裏門から長屋まで８ｍが縦羽目板張，長屋から南２７ｍが縦羽目板張と土壁で，内側は須柱に石の控え柱が付き，主屋から本蔵間が白漆喰塗，その他は土壁とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004011"},{"id":"00004008","register_sub_id":"101","register_pk":"104998","name":"中山家住宅本蔵及び裏門","kana":"なかやまけじゅうたくほんぐらおよびうらもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58929799,"lng":135.56475982,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0284","desc":"敷地の北を限る板塀に開く門と文庫蔵。長屋門形式である。外壁は敷地内側が白漆喰塗，外側が黒漆喰塗と舟板張に仕上げを変える。蔵は真壁造，門は主門と脇門一戸を開く。蔵の棟がやや高いが，北面の屋根を一連に造る。敷地北からの景観を引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004008"},{"id":"00003999","register_sub_id":"101","register_pk":"104989","name":"中山家住宅湯殿","kana":"なかやまけじゅうたくゆどの","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58891526,"lng":135.56450774,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0275","desc":"主屋の南西，奥座敷南に位置する木造平屋建の浴室。桁行２間梁間１間の切妻造，桟瓦葺。構造材に磨き丸太を用いた数寄屋風で，化粧小屋とする。外壁は漆喰塗の刷毛引き。２畳の脱衣場は両平に障子を建て，開放的である。風呂は溜風呂で，給湯用の戸口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003999"},{"id":"00004001","register_sub_id":"101","register_pk":"104991","name":"中山家住宅寮","kana":"なかやまけじゅうたくりょう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府松原市別所6-623","lat":34.58885181,"lng":135.56486181,"geo_status":"db","era":"江戸後期／明治前期改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"27 － 0277","desc":"敷地の東辺，長屋門と南蛮蔵の間に建つ木造平屋建，切妻造，桟瓦葺の長期滞在者用客間。桁行２間半梁間２間で，北面に床の間と押入を設ける。外壁は漆喰塗の真壁造で，腰を縦羽目板張とする。北へ半間延ばした屋根を本瓦葺とする。前庭景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004001"},{"id":"00003271","register_sub_id":"101","register_pk":"104261","name":"並河家住宅主屋","kana":"なみかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町8-1","lat":34.448734,"lng":135.358353,"geo_status":"db","era":"天保3","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積192㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0216","desc":"願泉寺住職で貝塚町を治めたト半家の重臣を勤めた家柄。主屋は切妻造本瓦葺で間口８間半の敷地幅一杯に建ち，街路に面する町家形式であるが，１階正面は比較的閉鎖的で，内部の店の間の上がり端に当たる場所に式台構を持つなど，商家の町家とは趣を異にする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003271"},{"id":"00003272","register_sub_id":"101","register_pk":"104262","name":"並河家住宅土蔵","kana":"なみかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市北町8-1","lat":34.448658,"lng":135.358475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"27 － 0217","desc":"並河家の敷地は願泉寺前面の街路に面し，間口８間半，奥行２１間の短冊形を呈する。土蔵は敷地のほぼ中央，主屋の背後にあり，敷地の間口方向に棟を置く切妻造本瓦葺，２階建てで，主屋側の西面に入り口を開く。敷地の構成要素として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003272"},{"id":"00002427","register_sub_id":"101","register_pk":"103417","name":"成子家住宅表門","kana":"なるこけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.363605,"lng":135.241364,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"木造、間口2.3m、西塀付","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0152","desc":"敷地の東南，表通りに面して主屋右手から連なる塀を従えて建ち，前庭を介して離れに開く門。一間棟門形式の簡素な造りとし，左右の塀より一間分控え，桟瓦葺の屋根を載せる。老舗の造り酒屋の接客空間への出入口として，控えめながらも重みのある意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002427"},{"id":"00002419","register_sub_id":"101","register_pk":"103409","name":"成子家住宅主屋","kana":"なるこけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.363781,"lng":135.241272,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積224㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0144","desc":"浪速酒造の店舗兼住宅。木造総２階建入母屋本瓦葺で，間口１１間にも及ぶ大型町屋。３列６間取りの平面で，書院化された座敷や２階の居室化等に近代の町屋の特質がみえる一方，２階の階高を低くし，開口部を全て虫駕窓とする等，伝統的な外観も保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002419"},{"id":"00002421","register_sub_id":"101","register_pk":"103411","name":"成子家住宅土蔵一","kana":"なるこけじゅうたくどぞういち","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.36383613,"lng":135.24145027,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0146","desc":"中庭を介して主屋と相対し，離れに隣接して建つ木造切妻，平屋建の土蔵。桁行３間半，梁間２間半の小規模な土蔵ながら，腰を下見板風の左官仕上げとし，屋根には本瓦を葺く丁寧な造り。内向きに配された主要な室から望む，中庭の重要な点景要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002421"},{"id":"00002422","register_sub_id":"101","register_pk":"103412","name":"成子家住宅土蔵二","kana":"なるこけじゅうたくどぞうに","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.36374248,"lng":135.24165125,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"土蔵造平屋建、瓦葺、建築面積68㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0147","desc":"敷地北東，離れと棟通りを揃えて建つ，桁行６間，梁間３間半規模の木造平屋建，切妻本瓦葺の土蔵。腰は，側面は土蔵一と同じく下見板風の左官仕上げとするが，観音扉を配する妻側正面には，開口部脇に額縁をまわして海鼠壁をはめるなど，特徴ある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002422"},{"id":"00002420","register_sub_id":"101","register_pk":"103410","name":"成子家住宅離れ","kana":"なるこけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.36364,"lng":135.24147,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0145","desc":"主屋東南部から矩折に連なる木造平屋建，桟瓦葺の離れ。玄関，座敷，離座敷，次の間，洋館等を配し，接客空間として充実した施設をもつ。座敷飾りを完備した座敷は随所に良質の材を用い，洋間も背の高い窓，蛇腹付の漆喰天井や中心飾りを備える本格的なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002420"},{"id":"00002428","register_sub_id":"101","register_pk":"103418","name":"成子家住宅塀","kana":"なるこけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府阪南市尾崎3-13-6","lat":34.36362229,"lng":135.24136913,"geo_status":"db","era":"大正年間","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正年間","structure":"煉瓦造、瓦葺、延長11m","structure_material":"煉瓦造","registered":"2001.10.12(平成13.10.12)","register_no":"27 － 0153","desc":"敷地東南，主屋から表門をはさんで延べ１０．５ｍにわたって表通りを区切る。基礎石に土壁風の仕上げとし桟瓦葺の屋根を載せる。酒蔵４から連なる主屋の本瓦葺の庇は，塀の瓦屋根と視覚的に一体化し，表通りの景観の連続性を保つ上で貴重な存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002428"},{"id":"00011985","register_sub_id":"101","register_pk":"211120","name":"西井家住宅内土蔵","kana":"にしいけじゅうたくうちどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市東区北野田284-1","lat":34.525008,"lng":135.545039,"geo_status":"db","era":"江戸後期／平成3年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積25㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"27 - 0708","desc":"敷地の東側、主屋の東端部に棟を直交させて接続する。桁行六・四メートル、梁間三・八メートルの土蔵造二階建、置屋根形式の本瓦葺で、主屋と接する西側に扉口を開く。外壁は腰竪板張、上部漆喰塗で、二階各所に小窓を開く。地域の歴史的景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011985"},{"id":"00011984","register_sub_id":"101","register_pk":"211119","name":"西井家住宅主屋","kana":"にしいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市東区北野田284-1","lat":34.525011,"lng":135.544925,"geo_status":"db","era":"江戸後期／平成3年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積209㎡、塀付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27 - 0707","desc":"木綿産地として知られた北野田地区に所在する民家。向かって右に土間を設け、土間脇に式台玄関をおく。西寄りの床上部は二列六室構成で、中の間の奥は仏間とし、西端部は南北共に座敷とする。屋根は茅葺で、近世に遡る大和棟の民家として希少である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011984"},{"id":"00011986","register_sub_id":"101","register_pk":"211121","name":"西井家住宅門長屋","kana":"にしいけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市東区北野田284-1","lat":34.524896,"lng":135.545094,"geo_status":"db","era":"天保5年（1834）／昭和初期改修、昭和3年頃曳家","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積102㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27 - 0709","desc":"木造平屋建、切妻造本瓦葺、桁行一九メートル、梁間三・九メートルで、西側に桟瓦葺の附属屋が取り付く。中央に大戸口を開き、東に衣装蔵、米蔵を、西に使用人の居室などを配し、附属屋部分には茶室、水屋を納める。地域の歴史的景観を形成する門長屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011986"},{"id":"00009798","register_sub_id":"101","register_pk":"195627","name":"西川家長屋","kana":"にしかわけながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区龍造寺町32-1他","lat":34.67701328,"lng":135.51882888,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積244㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"27 － 0573","desc":"小路沿いに南面する木造二階建の長屋。切妻造桟瓦葺で、前面に下屋を通し、出格子をたてる。東西に六戸を並べ、西端の住戸のみ広い。各戸は西寄りに土間を通し、東側に三室、背面に裏庭と便所を配する形式とする。大阪市内に多数建てられた長屋の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009798"},{"id":"00012582","register_sub_id":"101","register_pk":"367877","name":"西山家住宅主屋","kana":"にしやまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市岡町南二丁目13","lat":34.776554,"lng":135.462418,"geo_status":"geocoded","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積175㎡","structure_material":"木造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0755","desc":"阪急岡町駅西側に広がる住宅地のほぼ中央にあり、主屋は敷地北寄りに北面して建つ。東西棟平屋建の接客部と、その西側に接続する南北棟二階建の住居部からなる。接客と生活の動線を明快に分け、数寄屋風の茶室を備えるなど、近代郊外住宅の一類型を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012582"},{"id":"00012583","register_sub_id":"101","register_pk":"367878","name":"西山家住宅正門及び高塀","kana":"にしやまけじゅうたくせいもんおよびたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市岡町南二丁目13","lat":34.776554,"lng":135.462418,"geo_status":"geocoded","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"正門 木造、瓦葺、間口1.8m 高塀 木造、瓦葺、総延長13m","structure_material":"正門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"27 － 0756","desc":"敷地北面を区切る門と塀。正門は切妻造の腕木門で、楣上に精細な格子欄間を設け、前後に小庇を付す。門から矩折れで延びる高塀は真壁造で、腰高に縦板を大和打に張り、屋根は一文字瓦を葺く。近代郊外住宅地の落ち着きある佇まいの街路景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012583"},{"id":"00006694","register_sub_id":"101","register_pk":"107677","name":"西山家住宅高塀","kana":"にしやまけじゅうたくたかべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府豊中市岡町南二丁目１３","lat":34.77736982,"lng":135.46236488,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、延長49m","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0436","desc":"待合付近の屋敷地東南隅から東辺沿い北に延び、東北隅に矩折れに曲がる。コンクリート造基礎の上に建つ真壁造の塀で、腰高く焼杉板を大和打に張り、屋根には一文字瓦を葺く。落ち着きのある歴史的な街路景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006694"},{"id":"00006691","register_sub_id":"101","register_pk":"107674","name":"西山家住宅離れ及び待合","kana":"にしやまけじゅうたくはなれおよびまちあい","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市岡町南二丁目１３","lat":34.77718383,"lng":135.46225714,"geo_status":"db","era":"昭和4／昭和16増改築","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0433","desc":"南北に長い敷地の南側中央に南北棟で建つ。主体部を８畳と６畳の続き座敷とした入母屋造桟瓦葺のつし２階建で、東面南寄りに茶室と玄関を突き出し、玄関東方に待合を配する。茶室と待合は岡田孝男の設計で、離れの東・北２面には１枚ガラスの戸を建て込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006691"},{"id":"00006692","register_sub_id":"101","register_pk":"107675","name":"西山家住宅洋館","kana":"にしやまけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府豊中市岡町南二丁目１３","lat":34.7772599,"lng":135.46218728,"geo_status":"db","era":"大正初期／昭和14改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、鉄板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"27 － 0434","desc":"床下を物置とした高い鉄筋コンクリート造基礎の上に建ち、離れの西北端に階段で接続する。Ｌ字形の棟をもち、北面を半切妻とした寄棟造鉄板葺、木造平屋建の独立洋館で、南側を１０畳大の洋間とし、北方西側に３畳大の書斎を配し、東北隅部に玄関を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006692"}];
